local config = {
  ui_story_5087_50870100_1_dialog_content = "É uma fábula antiga conhecida por todos em Northland.",
  ui_story_5087_50870100_2_dialog_content = "E a primeira linha é...",
  ui_story_5087_50870100_3_dialog_content = "\"Você consegue se lembrar daquelas belas flores brancas?\"",
  ui_story_5087_50870100_4_dialog_content = "<color=#e8d9bb>Depois de lembrar a primeira frase, os fragmentos de memória restantes se ativam e surgem um por um.</color>",
  ui_story_5087_50870100_5_dialog_content = "<color=#e8d9bb>Um fogo alegre queima na lareira, sua luz quente cria sombras dançantes dentro da pequena cabana.</color>",
  ui_story_5087_50870100_6_dialog_content = "<color=#e8d9bb>No brilho do fogo, quatro figuras podem ser vistas: um marido e esposa, bem como suas filhas gêmeas que parecem imagens espelhadas uma da outra.</color>",
  ui_story_5087_50870100_7_dialog_content = "\"Você consegue se lembrar daquelas belas flores brancas? Dois caules crescendo em harmonia à beira do lago tranquilo.\"",
  ui_story_5087_50870100_8_dialog_content = "\"Um era um delicado narciso, o outro um lírio imaculado.\"",
  ui_story_5087_50870100_9_dialog_content = "\"Embora distintos em forma, suas almas eram uma.\"",
  ui_story_5087_50870100_10_dialog_content = "\"Um deles tinha folhas, o outro florescia com flores. Eles sorviam o orvalho da manhã, suas raízes para sempre entrelaçadas.\"",
  ui_story_5087_50870100_11_dialog_content = "Já que eles eram tão próximos, devem ter vivido juntos para sempre, certo?",
  ui_story_5087_50870100_12_dialog_content = "Infelizmente, toda história deve ter suas reviravoltas.",
  ui_story_5087_50870100_13_dialog_content = "\"Sob a neve cinza que caía, o lírio imaculado logo foi enterrado.\"",
  ui_story_5087_50870100_14_dialog_content = "\"Deixado sozinho no mundo, o narciso branco chorou silenciosamente.\"",
  ui_story_5087_50870100_15_dialog_content = "*solucando* Aquela pobre lírio... Deve ter sido tão frio sob toda aquela neve.",
  ui_story_5087_50870100_16_dialog_content = "Sinto mais pena do narciso. Não havia ninguém que pudesse ajudá-la?",
  ui_story_5087_50870100_17_dialog_content = "Vocês são duas meninas tão doces, assim como o lírio e o narciso. Northland jamais deixaria vocês chorarem sozinhas.",
  ui_story_5087_50870100_18_dialog_content = "Voltemos à história—",
  ui_story_5087_50870100_19_dialog_content = "\"Um dia, o Lago Espelho notou as raízes frias e as lágrimas tristes do narciso. Com pena dela, o lago prometeu trazer de volta a alma do lírio.\"",
  ui_story_5087_50870100_20_dialog_content = "O que aconteceu depois? A alma dela voltou?",
  ui_story_5087_50870100_21_dialog_content = "Eles conseguiram viver felizes para sempre novamente?",
  ui_story_5087_50870100_22_dialog_content = "Claro que sim! Como mais a história poderia terminar?",
  ui_story_5087_50870100_23_dialog_content = "Mas já passou muito da hora de dormir, meninas. Vamos terminar a história amanhã, combinado?",
  ui_story_5087_50870100_24_dialog_content = "Mentira! Quero ouvir agora!",
  ui_story_5087_50870100_25_dialog_content = "Você quer saber se o narciso ainda reconhece a alma do lírio, não é?",
  ui_story_5087_50870100_26_dialog_content = "Sim! Eu também quero saber se eles vão ficar juntos novamente e viver felizes para sempre!",
  ui_story_5087_50870100_27_dialog_content = "É claro que sim. Assim é como toda história acontece, não é?",
  ui_story_5087_50870100_28_dialog_content = "Não importa quantas voltas e reviravoltas a história dê...",
  ui_story_5087_50870100_29_dialog_content = "Todos sempre conseguem viver felizes para sempre.",
  ui_story_5087_50870100_30_dialog_content = "Isso mesmo. Lola uma vez disse que toda história tem um final feliz.",
  ui_story_5087_50870100_31_dialog_content = "Mas depois de todos esses anos, eu nem consigo me lembrar de ouvir essa história, muito menos do seu final.",
  ui_story_5087_50870100_32_dialog_content = "Uma sensação de inquietação me obrigou a buscar respostas, mas tudo que eu podia fazer era vasculhar os fragmentos caóticos das minhas memórias em busca delas.",
  ui_story_5087_50870100_33_dialog_content = "Então, como se meu desejo tivesse sido concedido, finalmente me lembrei de algo—",
  ui_story_5087_50870100_34_dialog_content = "Uma lareira quente, uma história contada por uma mãe e um pai, e duas meninas brincalhonas. Tudo parecia tão familiar, e ao mesmo tempo tão distante.",
  ui_story_5087_50870100_35_dialog_content = "Foi o meu passado? Mal consigo descobrir quem sou agora, mas o significado por trás do final daquela história é claro e definido.",
  ui_story_5087_50870100_36_dialog_content = "Eu esperava e rezava com todo o meu coração para que aquele final se tornasse realidade, mesmo que isso significasse... que eu nunca mais pudesse acordar.",
  ui_story_5087_50870100_37_dialog_content = "<color=#e8d9bb>\"A partir daquele dia, uma flor de lírio brotou do narciso, e ambos viveram felizes para sempre...\"</color>",
  ui_story_5087_50870100_38_dialog_content = "Felizes... para sempre...",
  ui_story_5087_50870100_39_dialog_content = "Isso mesmo, Nikinis. Você e eu estaremos sempre juntos, e viveremos felizes para sempre.",
  ui_story_5087_50870100_40_dialog_content = "...Hã?",
  ui_story_5087_50870100_41_dialog_content = "<color=#e8d9bb>Uma fragrância inebriante flutua por um campo de flores. O leve aroma de narcisos e o rico aroma de lírios se misturam no ar.</color>",
  ui_story_5087_50870100_42_dialog_content = "<color=#e8d9bb>No aroma das flores, alguém segura as mãos com Nikinis.</color>",
  ui_story_5087_50870100_43_dialog_content = "<color=#e8d9bb>Ela é tão pura e bela quanto um lírio branco. Embora diferem em corpo e mente, seus espíritos são um só.</color>",
  ui_story_5087_50870100_44_dialog_content = "N-Nepolis? É realmente você, irmã?",
  ui_story_5087_50870100_45_dialog_content = "Por que você parece tão surpreso, Nikinis? Não me diga que ficou doente novamente e esqueceu como eu pareço.",
  ui_story_5087_50870100_46_dialog_content = "Claro que não! Mas eu pensei que você estava preso em...",
  ui_story_5087_50870100_47_dialog_content = "(... Preso em quê? Por que não consigo me lembrar?)",
  ui_story_5087_50870100_48_dialog_content = "... Espere, Nepolis, não vá! Fique comigo!",
  ui_story_5087_50870100_49_dialog_content = "Oh? Parece que eu não estava imaginando coisas afinal. Desde que nos recuperamos da nossa doença, você se tornou muito mais apegado.",
  ui_story_5087_50870100_50_dialog_content = "Mas não se preocupe, Nikinis. Estou realmente bem aqui ao seu lado.",
  ui_story_5087_50870100_51_dialog_content = "Não é uma ilusão em um espelho, nem um reflexo na água.",
  ui_story_5087_50870100_52_dialog_content = "Seu rosto está tão quente, Nepolis... Você realmente voltou de novo?",
  ui_story_5087_50870100_53_dialog_content = "(... Por que eu disse \"de volta novamente\"?)",
  ui_story_5087_50870100_54_dialog_content = "Sempre que estamos juntos, sinto que não consigo nem esconder meus pensamentos de você.",
  ui_story_5087_50870100_55_dialog_content = "Sempre consegui entender o que você está pensando, e o mesmo vale para você e meus pensamentos. Esse é o nosso dom e a nossa maneira de mostrar que sempre teremos um ao outro.",
  ui_story_5087_50870100_56_dialog_content = "Agora me dê sua mão e caminhe comigo. Você se lembrará das coisas em breve.",
  ui_story_5087_50870100_57_dialog_content = "Como gêmeos, compartilhamos as mesmas raízes e caules. Nascidos com Luminatics muito especiais, nossos corações e almas estão conectados.",
  ui_story_5087_50870100_58_dialog_content = "Se eu ficar com sede...",
  ui_story_5087_50870100_59_dialog_content = "... Então eu também estarei com sede.",
  ui_story_5087_50870100_60_dialog_content = "Se eu decidir sair...",
  ui_story_5087_50870100_61_dialog_content = "... Eu já vou ter nossos casacos e botas prontos.",
  ui_story_5087_50870100_62_dialog_content = "Isso mesmo! Nossa aparência, nossos hobbies, nossos talentos... Você e eu somos um e o mesmo, Nikinis.",
  ui_story_5087_50870100_63_dialog_content = "Plantamos este campo de flores juntos, entramos no Palácio de Inverno juntos e conquistamos a honra de servir Queen Bethlehem juntos.",
  ui_story_5087_50870100_64_dialog_content = "Você... realmente não se lembra de nada?",
  ui_story_5087_50870100_65_dialog_content = "Não... Eu me lembro de tudo agora. Quanto mais você me conta sobre nosso passado, mais memórias aparecem em minha mente.",
  ui_story_5087_50870100_66_dialog_content = "Toda vez que você sorri com nostalgia, sinto a mesma felicidade no meu coração também.",
  ui_story_5087_50870100_67_dialog_content = "Estar com você me faz sentir tão... completo - ou pelo menos é assim que eu descreveria.",
  ui_story_5087_50870100_68_dialog_content = "Não consigo imaginar viver sem você.",
  ui_story_5087_50870100_69_dialog_content = "Você está falando sobre a época em que nós dois adoecemos, certo? Aquilo foi um período tão assustador...",
  ui_story_5087_50870100_70_dialog_content = "Eu me sentia tão fraco e apático todos os dias. Eu nem mesmo conseguia sentir meus próprios membros, muito menos você.",
  ui_story_5087_50870100_71_dialog_content = "Acho que essa foi a primeira vez que perdemos nossa conexão um com o outro.",
  ui_story_5087_50870100_72_dialog_content = "Isso mesmo... Eu também fiquei doente, é por isso que minhas memórias e sentimentos se tornaram tão confusos.",
  ui_story_5087_50870100_73_dialog_content = "Hehe... Então ainda somos os mesmos de quando éramos crianças, compartilhando cada momento de dor e tristeza.",
  ui_story_5087_50870100_74_dialog_content = "Para ser honesto, é um pouco inconveniente. Quando um de nós ficava doente, o outro seguia o mesmo caminho... Nossos pais devem ter se preocupado muito!",
  ui_story_5087_50870100_75_dialog_content = "Nossos pais... Isso mesmo! Eles estão bem? Posso ir para casa e vê-los?",
  ui_story_5087_50870100_76_dialog_content = "Claro. Mas antes de irmos para casa, temos que terminar nossa missão.",
  ui_story_5087_50870100_77_dialog_content = "Nossa missão?",
  ui_story_5087_50870100_78_dialog_content = "O quê, você esqueceu toda a missão de Sua Majestade depois de um pequeno cochilo?",
  ui_story_5087_50870100_79_dialog_content = "A rainha nos ordenou recuperar um artefato perdido da floresta.",
  ui_story_5087_50870201_1_dialog_content = "Não temos muito tempo, então vamos fazer as coisas do jeito usual. Vamos limpar a neve à medida que avançamos!",
  ui_story_5087_50870201_2_dialog_content = "Beleza!",
  ui_story_5087_50870201_3_dialog_content = "Nossa missão é... recuperar um artefato perdido para Queen Bethlehem?",
  ui_story_5087_50870201_4_dialog_content = "Sim. Uma relíquia foi roubada do cofre do Palácio de Inverno. É um objeto perigoso que pode perturbar o espírito de uma pessoa.",
  ui_story_5087_50870201_5_dialog_content = "A rainha teme que cause sofrimento incontável se cair nas mãos das pessoas, então ela enviou muitos de seus leais servidores para procurá-lo.",
  ui_story_5087_50870201_6_dialog_content = "Roubado? Que tipo de ladrão seria tolo o suficiente para fazer algo assim?",
  ui_story_5087_50870201_7_dialog_content = "Heehee, acho que uma pergunta melhor seria que tipo de rainha seria tão misericordiosa a respeito disso?",
  ui_story_5087_50870201_8_dialog_content = "Uma relíquia inestimável é roubada de seu palácio, e sua primeira preocupação é recuperá-la antes que possa ameaçar a segurança de seu povo. Para Sua Majestade, a captura do ladrão tem muito menos precedência.",
  ui_story_5087_50870201_9_dialog_content = "A rainha sempre foi assim.",
  ui_story_5087_50870201_10_dialog_content = "Não consigo contar o número de histórias que ouvi sobre Sua Majestade resolvendo todos os tipos de problemas para seu povo.",
  ui_story_5087_50870201_11_dialog_content = "Mesmo que fosse algo tão trivial quanto resgatar o gado da floresta ou limpar a neve das estradas da montanha...",
  ui_story_5087_50870201_12_dialog_content = "Pelo menos não temos que nos preocupar com a neve, certo? Vê como trabalhamos bem juntos? Ei, este lado é meu!",
  ui_story_5087_50870201_13_dialog_content = "A rainha cuidou de nós pelo tempo que consigo me lembrar...",
  ui_story_5087_50870201_14_dialog_content = "Ela até curou minha doença.",
  ui_story_5087_50870201_15_dialog_content = "É por isso que você escolheu ficar no Palácio de Inverno e servi-la.",
  ui_story_5087_50870201_16_dialog_content = "Tenho certeza que ela também curou sua doença.",
  ui_story_5087_50870201_17_dialog_content = "Desde que você se sinta melhor, eu também me sinto. Não há necessidade de incomodar a rainha com isso.",
  ui_story_5087_50870201_18_dialog_content = "Mais um! Ufa, finalmente conseguimos.",
  ui_story_5087_50870201_19_dialog_content = "Alguém relatou ter visto o artefato roubado em algum lugar perto daquela casa de campo à frente.",
  ui_story_5087_50870201_20_dialog_content = "Olá, tem alguém em casa? Fomos enviados pelo Palácio Invernal.",
  ui_story_5087_50870201_21_dialog_content = "<color=#e8d9bb>O interior da cabana está mortalmente silencioso.</color>",
  ui_story_5087_50870201_22_dialog_content = "(Sem resposta... Huh? Pisei em algo brilhante... um caco quebrado de algum tipo?)",
  ui_story_5087_50870201_23_dialog_content = "O que é isso, Nikinis?",
  ui_story_5087_50870201_24_dialog_content = "Cuidado, Nepólis. Eu tenho...",
  ui_story_5087_50870201_25_dialog_content = "... Um mau pressentimento sobre isso.",
  ui_story_5087_50870201_26_dialog_content = "<color=#e8d9bb>As irmãs gêmeas colocam uma mão na porta. Ficando de cada lado dela, elas cuidadosamente a empurram para abrir.</color>",
  ui_story_5087_50870201_27_dialog_content = "!",
  ui_story_5087_50870201_28_dialog_content = "É isso... um espelho?",
  ui_story_5087_50870201_29_dialog_content = "Está completamente quebrado...",
  ui_story_5087_50870201_30_dialog_content = "(O que está acontecendo? Por algum motivo, este espelho parece tão familiar para mim...)",
  ui_story_5087_50870201_31_dialog_content = "(Huh? Acabei de ver uma pessoa no espelho?)",
  ui_story_5087_50870201_32_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870201_33_dialog_content = "Quem é você? Por que está me chamando? E... o que está fazendo neste espelho?",
  ui_story_5087_50870201_34_dialog_content = "Nikinis... Não...",
  ui_story_5087_50870201_35_dialog_content = "Eu não posso te ouvir.",
  ui_story_5087_50870201_36_dialog_content = "Pare! Não dê outro passo!",
  ui_story_5087_50870201_37_dialog_content = "!",
  ui_story_5087_50870201_38_dialog_content = "Esse é o relicário roubado do Palácio Invernal, Nikinis!",
  ui_story_5087_50870201_39_dialog_content = "É chamado de Espelho de Northland, e é um dos objetos mais perigosos na coleção da rainha!",
  ui_story_5087_50870201_40_dialog_content = "O que seria?",
  ui_story_5087_50870201_41_dialog_content = "(Então por que alguém dentro deste artefato perigoso chamaria por mim?)",
  ui_story_5087_50870201_42_dialog_content = "Cuidado, Nikinis!",
  ui_story_5087_50870201_43_dialog_content = "<color=#e8d9bb>Assustado, Nikinis só consegue ver os cacos espalhados do espelho começarem a tremer.</color>",
  ui_story_5087_50870201_44_dialog_content = "<color=#e8d9bb>De repente, inúmeros feixes de escuridão irrompem dos fragmentos e convergem.</color>",
  ui_story_5087_50870201_45_dialog_content = "<color=#e8d9bb>Uma presença indistinta, não diferente de uma sombra.</color>",
  ui_story_5087_50870201_46_dialog_content = "Mantenha-se longe da minha irmã!",
  ui_story_5087_50870202_1_dialog_content = "Nepolis! Está ferido? Eu posso sentir sua dor—",
  ui_story_5087_50870202_2_dialog_content = "Não é hora de manter nossa conexão, bobo. Se você compartilhar minha dor, ambas as nossas vidas estarão em perigo nas batalhas.",
  ui_story_5087_50870202_3_dialog_content = "Desculpe... Mas você se machucou por minha causa...",
  ui_story_5087_50870202_4_dialog_content = "Não havia o que fazer. Afinal, você teria feito o mesmo por mim, certo?",
  ui_story_5087_50870202_5_dialog_content = "O que aconteceu com você agora mesmo? Não é nada parecido com você se aproximar daquele espelho mágico de forma tão imprudente.",
  ui_story_5087_50870202_6_dialog_content = "Estou tendo dificuldades para entender suas emoções agora...",
  ui_story_5087_50870202_7_dialog_content = "É só que... Eu vi alguém se movendo no espelho, então eu quis dar uma olhada mais de perto.",
  ui_story_5087_50870202_8_dialog_content = "Você viu alguém? Tem certeza de que não eram apenas nossos reflexos?",
  ui_story_5087_50870202_9_dialog_content = "Eu... acho que não? Deixe-me ir dar outra olhada-",
  ui_story_5087_50870202_10_dialog_content = "Não acho que seja uma boa ideia. Esse espelho é muito perigoso, e não há como prever o que pode acontecer conosco se nos aproximarmos dele.",
  ui_story_5087_50870202_11_dialog_content = "Vamos usar nossa Luminática para empacotá-lo e transportá-lo de volta ao Palácio de Inverno.",
  ui_story_5087_50870202_12_dialog_content = "... Você está certo, Nepolis. Vamos lá.",
  ui_story_5087_50870202_13_dialog_content = "<color=#e8d9bb>As duas irmãs ativam suas Lumináticas simultaneamente. Ramos verdes crescem do chão em ambos os lados do espelho e florescem com flores brancas.</color>",
  ui_story_5087_50870202_14_dialog_content = "<color=#e8d9bb>Em breve, toda a cabana é preenchida com o cheiro de flores. À medida que os ramos florescentes sobem pelas paredes da cabana, o espelho quebrado é envolvido firmemente.</color>",
  ui_story_5087_50870202_15_dialog_content = "Urgh! Tem algo no espelho... e está tentando sair!",
  ui_story_5087_50870202_16_dialog_content = "Apenas espere! Estou chegando!",
  ui_story_5087_50870202_17_dialog_content = "Ufa...",
  ui_story_5087_50870202_18_dialog_content = "Heheh, parece que conseguimos, hein? Eu não esperava menos de nós, irmãs!",
  ui_story_5087_50870202_19_dialog_content = "Você merece todo o crédito, Nepolis... Faz tanto tempo desde a minha última luta que esqueci de tomar precauções.",
  ui_story_5087_50870202_20_dialog_content = "Acho que eu não poderia ter lidado com isso sem você...",
  ui_story_5087_50870202_21_dialog_content = "De maneira nenhuma! Posso dizer o quão poderoso você é apenas olhando para estas flores.",
  ui_story_5087_50870202_22_dialog_content = "Vê? Apenas olhe como eles estão florescendo bem!",
  ui_story_5087_50870202_23_dialog_content = "<color=#e8d9bb>Pelo poder de seus Luminatics, a cabana está enterrada sob um mar de flores brancas puras.</color>",
  ui_story_5087_50870202_24_dialog_content = "<color=#e8d9bb>Narcisos delicados e lírios imaculados, nascidos lado a lado.</color>",
  ui_story_5087_50870202_25_dialog_content = "Nossas flores florescendo juntas... Por algum motivo, parece que não vejo algo assim há muito tempo...",
  ui_story_5087_50870202_26_dialog_content = "\"Você consegue se lembrar daquelas belas flores brancas?\"",
  ui_story_5087_50870202_27_dialog_content = "As flores de Nepolis... Ah.",
  ui_story_5087_50870202_28_dialog_content = "Estou bem aqui, lembra? Você não precisa continuar olhando para as minhas flores, sabe.",
  ui_story_5087_50870202_29_dialog_content = "Uma vez que retornarmos do Palácio Invernal, podemos voltar ao Lago Espelho e cuidar do nosso campo de flores!",
  ui_story_5087_50870300_1_dialog_content = "<color=#e8d9bb>O Palácio Invernal é o assento da autoridade real em Northland e um lugar há muito considerado sagrado pelos Northlanders.</color>",
  ui_story_5087_50870300_2_dialog_content = "Incrível... Vocês dois realmente conseguiram recuperar o Espelho de Northland! Mal posso acreditar nisso!",
  ui_story_5087_50870300_3_dialog_content = "Foi tudo graças à minha irmã...",
  ui_story_5087_50870300_4_dialog_content = "Não seja tão modesto, Nikinis! Olha, eles até nos serviram um pouco do chá mais precioso de Sua Majestade.",
  ui_story_5087_50870300_5_dialog_content = "Essas coisas não são baratas, sabe? Da última vez que eu quis uma xícara, implorei por três dias seguidos, mas eles ainda me recusaram.",
  ui_story_5087_50870300_6_dialog_content = "Hahaha, bem... Como você sabe, o roubo do Espelho do Norte foi um assunto bastante sério!",
  ui_story_5087_50870300_7_dialog_content = "Dizem que essa relíquia é ainda mais antiga que o Palácio Invernal e ocupa um lugar muito único na coleção da rainha.",
  ui_story_5087_50870300_8_dialog_content = "Para desaparecer no meio da noite sem deixar rastros... o pobre Mestre Novio mal dormiu desde então!",
  ui_story_5087_50870300_9_dialog_content = "Agora que está de volta em nossa posse, a realeza pode se poupar de ainda mais noites sem dormir... pelo menos por enquanto! Hahaha!",
  ui_story_5087_50870300_10_dialog_content = "Temos a honra de ajudar o Mestre Novio com algo tão importante. Infelizmente, não encontramos nenhuma pista sobre o ladrão...",
  ui_story_5087_50870300_11_dialog_content = "...",
  ui_story_5087_50870300_12_dialog_content = "Hmm? Qual o problema, Nikinis? Você parece inquieto... Está nervoso por estar no grande Palácio de Inverno?",
  ui_story_5087_50870300_13_dialog_content = "Sinceramente, eu gostaria que você não me provocasse tanto às vezes.",
  ui_story_5087_50870300_14_dialog_content = "É só que... O Palácio Invernal parece um pouco diferente hoje.",
  ui_story_5087_50870300_15_dialog_content = "O que há de diferente nisso?",
  ui_story_5087_50870300_16_dialog_content = "(Não tenho certeza... Por que é tão difícil lembrar como o Palácio Invernal era antes?)",
  ui_story_5087_50870300_17_dialog_content = "Não consigo identificar exatamente... Talvez esteja especialmente limpo hoje? Está tão brilhante e claro que parece que algo está faltando...",
  ui_story_5087_50870300_18_dialog_content = "E aqui eu pensava que você era todo sobre limpeza.",
  ui_story_5087_50870300_19_dialog_content = "Vossa Majestade!",
  ui_story_5087_50870300_20_dialog_content = "V-Vossa Majestade! Perdoe-nos se nossas brigas ofenderam você...",
  ui_story_5087_50870300_21_dialog_content = "Não havia nada para se ofender, Nikinis. Na verdade, eu concordo com você. Quando um espaço é limpo demais, pode ser um pouco perturbador.",
  ui_story_5087_50870300_22_dialog_content = "Um palácio deveria ter mais sinais de vida, como fumaça de vela e folhas de chá descartadas. Talvez eu possa pedir ao Noah e aos outros para me ajudarem com isso.",
  ui_story_5087_50870300_23_dialog_content = "I-Isso não foi o que eu quis dizer, Vossa Majestade...",
  ui_story_5087_50870300_24_dialog_content = "Acho que a rainha está nos dizendo que devemos visitar mais vezes, irmã.",
  ui_story_5087_50870300_25_dialog_content = "Se participarmos do clube de leitura e das sessões de chá da tarde de Sua Majestade, adicionaremos mais \"sinais de vida\" ao palácio!",
  ui_story_5087_50870300_26_dialog_content = "Cuidado, Nepólis! Não se queime tão seriamente por algo como chá...",
  ui_story_5087_50870300_27_dialog_content = "Heheh... Minha irmã pode ser tão adorável às vezes. Não concorda, Vossa Majestade?",
  ui_story_5087_50870300_28_dialog_content = "Népolis!",
  ui_story_5087_50870300_29_dialog_content = "Como irmãs, vocês duas não poderiam ser mais próximas. Seu vínculo concede a ambas força e unidade, e essa é a razão pela qual vocês conseguiram recuperar o Espelho Northland.",
  ui_story_5087_50870300_30_dialog_content = "Seu trabalho é muito apreciado, Nepolis e Nikinis.",
  ui_story_5087_50870300_31_dialog_content = "Estávamos apenas cumprindo nosso dever de manter Northland segura.",
  ui_story_5087_50870300_32_dialog_content = "Vossa Majestade, posso perguntar... o que aconteceu com aquele espelho?",
  ui_story_5087_50870300_33_dialog_content = "O Espelho de Northland pode converter tudo o que reflete em poder, que é então transformado em monstros feitos de sombras.",
  ui_story_5087_50870300_34_dialog_content = "Eu selei tanto o espelho quanto o monstro que mora dentro dele. Não representa nenhuma ameaça por enquanto.",
  ui_story_5087_50870300_35_dialog_content = "Ainda temos muito a investigar em relação ao seu roubo. Diga-me, você notou algo incomum no lugar onde o encontrou?",
  ui_story_5087_50870300_36_dialog_content = "... Na verdade, tudo sobre a cena era incomum.",
  ui_story_5087_50870300_37_dialog_content = "Não havia mais ninguém na cabana onde o espelho estava escondido, nem qualquer sinal do ladrão, aliás...",
  ui_story_5087_50870300_38_dialog_content = "Quando entramos na cabana, o espelho já havia sido estilhaçado. Não havia pistas sobre quem o estilhaçou ou por que fizeram isso...",
  ui_story_5087_50870300_39_dialog_content = "O chão estava coberto com os fragmentos quebrados do espelho, e logo vários feixes de escuridão escaparam deles. Eles eram muito parecidos com os monstros sombrios que você acabou de descrever, Vossa Majestade...",
  ui_story_5087_50870300_40_dialog_content = "Nikinis disse que também viu uma figura misteriosa no espelho.",
  ui_story_5087_50870300_41_dialog_content = "...",
  ui_story_5087_50870300_42_dialog_content = "Monstros sombrios e uma figura misteriosa... Temo que todos sejam produtos do poder do Espelho de Northland.",
  ui_story_5087_50870300_43_dialog_content = "É provável que o ladrão tenha ativado acidentalmente o espelho ao ser pego em seu reflexo.",
  ui_story_5087_50870300_44_dialog_content = "Se o que você disse é verdade, selar o próprio espelho não será suficiente para garantir a segurança do reino.",
  ui_story_5087_50870300_45_dialog_content = "Temo que os fragmentos do espelho também contenham partes do poder desses monstros. Para a segurança de nosso povo, todos eles devem ser recuperados.",
  ui_story_5087_50870300_46_dialog_content = "May Eu confio a vocês dois esta missão também?",
  ui_story_5087_50870300_47_dialog_content = "Claro, Vossa Majestade! Somos gratos por qualquer oportunidade de servi-lo.",
  ui_story_5087_50870300_48_dialog_content = "Vossa Majestade... May Posso fazer uma pergunta?",
  ui_story_5087_50870300_49_dialog_content = "Por todos os meios.",
  ui_story_5087_50870300_50_dialog_content = "Algo naquele espelho parecia incrivelmente familiar, como se tivéssemos nos visto há muito tempo...",
  ui_story_5087_50870300_51_dialog_content = "Você poderia explicar por que me senti assim?",
  ui_story_5087_50870300_52_dialog_content = "Sério? Isso é estranho. Eu não senti nada disso.",
  ui_story_5087_50870300_53_dialog_content = "... Parece que não adianta esconder isso de você, Nikinis.",
  ui_story_5087_50870300_54_dialog_content = "Sua intuição está completamente correta. Você realmente encontrou o Espelho de Northland uma vez antes.",
  ui_story_5087_50870300_55_dialog_content = "Eu sabia!",
  ui_story_5087_50870300_56_dialog_content = "Aconteceu quando vocês dois adoeceram.",
  ui_story_5087_50870300_57_dialog_content = "Na época, Nepolis estava assolada por uma febre terrível, mas você estava perfeitamente saudável. Com o tempo, no entanto, você começou a apresentar sintomas semelhantes.",
  ui_story_5087_50870300_58_dialog_content = "Vocês dois sempre foram assim. Sua conexão de corpo e alma torna vocês duas vezes mais poderosos, mas também duas vezes mais vulneráveis.",
  ui_story_5087_50870300_59_dialog_content = "Seus pais procuraram desesperadamente a ajuda de vários médicos, mas todos sem sucesso. Eventualmente, eles não tiveram escolha a não ser trazê-lo ao palácio e pedir minha assistência.",
  ui_story_5087_50870300_60_dialog_content = "Para evitar qualquer interrupção na sua recuperação, minha primeira escolha de ação foi cortar temporariamente sua conexão.",
  ui_story_5087_50870300_61_dialog_content = "Para isso, eu precisava de uma relíquia poderosa capaz de influenciar as almas dos seres vivos—",
  ui_story_5087_50870300_62_dialog_content = "O Espelho de Northland!",
  ui_story_5087_50870300_63_dialog_content = "Exatamente. Naquela época, você mostrou uma afinidade extremamente alta pelo Espelho do Northland.",
  ui_story_5087_50870300_64_dialog_content = "É também por isso que consegui separar vocês dois com sucesso e curar suas doenças.",
  ui_story_5087_50870300_65_dialog_content = "...",
  ui_story_5087_50870300_66_dialog_content = "Entendo... Acho que me lembro vagamente de nossos pais nos levando ao Palácio Invernal para tratamento...",
  ui_story_5087_50870300_67_dialog_content = "É por isso que parecia tão familiar! Eu devo minha vida àquele espelho...",
  ui_story_5087_50870300_68_dialog_content = "... Essa é a verdade dos fatos. E agora que você lembra, não tenho motivo para negar.",
  ui_story_5087_50870300_69_dialog_content = "Mas há uma coisa que você deve sempre lembrar - nunca se aproxime do espelho e nunca acredite nas palavras ditas por seus reflexos.",
  ui_story_5087_50870300_70_dialog_content = "Como uma das relíquias mais antigas e poderosas de Northland, ela é cercada por perigo e mistério em medidas igualmente altas.",
  ui_story_5087_50870300_71_dialog_content = "Até as antigas civilizações, que eram capazes de criar maravilhas como o Farol e os Colossos—",
  ui_story_5087_50870300_72_dialog_content = "Eles estavam a eras de distância de compreender totalmente o poder do espelho.",
  ui_story_5087_50870400_1_dialog_content = "Fora, monstros!",
  ui_story_5087_50870400_2_dialog_content = "Graaah...",
  ui_story_5087_50870400_3_dialog_content = "Nada mal! Nesse ritmo, encontraremos o resto dos fragmentos do espelho em pouco tempo, e nossa missão estará completa.",
  ui_story_5087_50870400_4_dialog_content = "... E tudo graças à sua capacidade de sentir a presença do espelho.",
  ui_story_5087_50870400_5_dialog_content = "Estou apenas feliz por finalmente poder ser útil, Nepolis! Na verdade, deixe-me ver se há mais fragmentos por perto.",
  ui_story_5087_50870400_6_dialog_content = "... Claro. Estou contando com você.",
  ui_story_5087_50870400_7_dialog_content = "Huh? Qual é o problema, Nepolis? Você parece um pouco melancólico.",
  ui_story_5087_50870400_8_dialog_content = "N-Não! Se for o caso, você é quem está agindo de maneira diferente! O que deu em você?",
  ui_story_5087_50870400_9_dialog_content = "Acho que não tem como esconder isso de você.",
  ui_story_5087_50870400_10_dialog_content = "Você se lembra do que Queen Bethlehem nos contou sobre o Espelho de Northland?",
  ui_story_5087_50870400_11_dialog_content = "Claro. Ela disse que os poderes do espelho não se limitam apenas a criar monstros...",
  ui_story_5087_50870400_12_dialog_content = "Pode usar qualquer coisa capturada em seu reflexo para criar ilusões realistas, que podem então influenciar as pessoas até suas próprias almas.",
  ui_story_5087_50870400_13_dialog_content = "Porque foi criado por uma civilização desconhecida há eras atrás, o espelho contém um poder avassalador e primordial...",
  ui_story_5087_50870400_14_dialog_content = "Nem a rainha nem as civilizações de antes do nosso tempo conseguiram compreendê-lo totalmente...",
  ui_story_5087_50870400_15_dialog_content = "Até as organizações mais heréticas de Northland, aquelas que são especialistas em relíquias antigas como esta, estão totalmente perplexas com sua magia.",
  ui_story_5087_50870400_16_dialog_content = "Para desbloquear o potencial total de uma relíquia tão poderosa, é necessário um hospedeiro adequado como seu recipiente...",
  ui_story_5087_50870400_17_dialog_content = "Mas tornar-se seu hospedeiro resulta em uma chance muito maior de morrer antes de obter seu poder.",
  ui_story_5087_50870400_18_dialog_content = "Nepolis... Apesar de quão perigoso este espelho pode ser, Queen Bethlehem correu o risco de usá-lo para nos salvar...",
  ui_story_5087_50870400_19_dialog_content = "Agora que sabemos a verdade, é a nossa vez de retribuir... Mas até agora, tudo o que fiz foi confiar na sua força.",
  ui_story_5087_50870400_20_dialog_content = "Com minha habilidade de sentir a presença do espelho, finalmente posso ajudá-lo—",
  ui_story_5087_50870400_21_dialog_content = "... Pare!",
  ui_story_5087_50870400_22_dialog_content = "N-Népolis?",
  ui_story_5087_50870400_23_dialog_content = "Não podemos confiar muito na sua afinidade com o espelho, nem deixar sua alma se aproximar demais dele.",
  ui_story_5087_50870400_24_dialog_content = "\"Quem quer que seja escolhido pelo espelho para se tornar seu hospedeiro tem uma chance maior de morrer antes de obter seu poder.\" Você já esqueceu o que a rainha nos disse?",
  ui_story_5087_50870400_25_dialog_content = "Precisamos nos apressar e coletar os fragmentos restantes, e então você não poderá mais se aproximar disso.",
  ui_story_5087_50870400_26_dialog_content = "Depois que nossa missão terminar, finalmente poderemos voltar para nosso campo de flores. Estaremos seguros, e nossos corações e mentes serão um novamente...",
  ui_story_5087_50870400_27_dialog_content = "C-Claro! Prometo que não vou me aproximar precipitadamente do espelho de novo!",
  ui_story_5087_50870400_28_dialog_content = "... E se tivermos que nos aproximar dele, deixe-me ir em seu lugar. Afinal, eu não tenho afinidade com ele.",
  ui_story_5087_50870400_29_dialog_content = "Toda vez que falamos sobre o espelho, parece que você está se afastando mais de mim...",
  ui_story_5087_50870400_30_dialog_content = "Graah!",
  ui_story_5087_50870400_31_dialog_content = "Nepólis! Os monstros do espelho também estão vindo daqui!",
  ui_story_5087_50870400_32_dialog_content = "Mova-se, Nikinis!",
  ui_story_5087_50870400_33_dialog_content = "Deixe a floresta comigo! ... Hã? Por que aquele se parece diferente do resto?",
  ui_story_5087_50870400_34_dialog_content = "Segure-o aí, monstro!",
  ui_story_5087_50870400_35_dialog_content = "Pra onde ele foi?",
  ui_story_5087_50870400_36_dialog_content = "(Isso não era uma ilusão agora. Parecia que era feito de cristais de gelo... Isso poderia ser obra do Espelho de Northland também?)",
  ui_story_5087_50870400_37_dialog_content = "<color=#e8d9bb>De repente, um farfalhar pode ser ouvido mais profundamente na floresta.</color>",
  ui_story_5087_50870400_38_dialog_content = "(... Está chegando!)",
  ui_story_5087_50870400_39_dialog_content = "...",
  ui_story_5087_50870400_40_dialog_content = "U-Uma garotinha?",
  ui_story_5087_50870501_1_dialog_content = "Boa tarde.",
  ui_story_5087_50870501_2_dialog_content = "(Esta criança parece totalmente calma...)",
  ui_story_5087_50870501_3_dialog_content = "O que você está fazendo sozinha na floresta, garotinha? Sua casa é perto daqui?",
  ui_story_5087_50870501_4_dialog_content = "Estou... vendendo coisas.",
  ui_story_5087_50870501_5_dialog_content = "Ah, sim, você está carregando uma cesta de flores. É isso que você está vendendo?",
  ui_story_5087_50870501_6_dialog_content = "Tenho outros itens à venda também, mas ainda não fiz nenhum negócio. Portanto, não estou pronto para ir para casa.",
  ui_story_5087_50870501_7_dialog_content = "\"Como tal\"? Heheh, para alguém tão jovem, você certamente sabe como falar como um adulto. Estou impressionado!",
  ui_story_5087_50870501_8_dialog_content = "E-Eu aprendi com minha mãe e meu pai!",
  ui_story_5087_50870501_9_dialog_content = "Não se preocupe, eu não sou uma pessoa ruim. A floresta pode ser um lugar perigoso, sabe? Há até um monstro à solta agora mesmo.",
  ui_story_5087_50870501_10_dialog_content = "Você sabe como chegar em casa? Posso te escoltar de volta, se você quiser.",
  ui_story_5087_50870501_11_dialog_content = "Eu não tenho medo de monstros.",
  ui_story_5087_50870501_12_dialog_content = "É-É isso mesmo? Acho que você deveria pelo menos ter um pouco de medo deles...",
  ui_story_5087_50870501_13_dialog_content = "A única coisa que temo é não poder ajudar minha família com seu fardo. Então, poderia me ajudar comprando algo, senhorita?",
  ui_story_5087_50870501_14_dialog_content = "Como este espelho de mão, por exemplo. Não é simplesmente adorável?",
  ui_story_5087_50870501_15_dialog_content = "!",
  ui_story_5087_50870501_16_dialog_content = "(Espere, acho que é apenas um espelho comum. Graças a Deus... Ainda assim, não acho que Nepólis apreciaria se eu voltasse com um espelho.)",
  ui_story_5087_50870501_17_dialog_content = "Me desculpe, querido, mas eu tenho tido muito azar com espelhos ultimamente.",
  ui_story_5087_50870501_18_dialog_content = "... Multar.",
  ui_story_5087_50870501_19_dialog_content = "Então... Que tal algumas flores recém-cortadas? Você estaria disposto a comprar algumas?",
  ui_story_5087_50870501_20_dialog_content = "Viu? Tenho rosas amarelas, não-me-esqueças e até alguns narcisos brancos! Um deles deve chamar sua atenção, certo?",
  ui_story_5087_50870501_21_dialog_content = "Que coincidência! Acontece que eu amo todas essas flores mais do que tudo!",
  ui_story_5087_50870501_22_dialog_content = "Estou feliz em ouvir isso, senhorita.",
  ui_story_5087_50870501_23_dialog_content = "Então você deve saber o que eles <color=#FFB400>simbolizam</color>, sim?",
  ui_story_5087_50870501_24_dialog_content = "O que eles simbolizam...",
  ui_story_5087_50870501_25_dialog_content = "Mais flores? Que gentileza sua, Nikinis. Então, o que você me trouxe hoje? Rosas amarelas e não-me-esqueças?",
  ui_story_5087_50870501_26_dialog_content = "Sim, Vossa Majestade. Eu sempre quis lhe presentear com essas flores por causa do que elas simbolizam—",
  ui_story_5087_50870501_27_dialog_content = "(Aquela memória que acabei de ver em minha mente... Quando isso aconteceu?)",
  ui_story_5087_50870501_28_dialog_content = "(Quando olho para essa garotinha... por que de repente me lembro da rainha?)",
  ui_story_5087_50870501_29_dialog_content = "... Nikinis! Atenção!",
  ui_story_5087_50870501_30_dialog_content = "Graaah!",
  ui_story_5087_50870501_31_dialog_content = "Fique atrás de mim, garotinha!",
  ui_story_5087_50870501_32_dialog_content = "Receio que não possa fazer isso.",
  ui_story_5087_50870501_33_dialog_content = "Não importa onde eu esteja, preciso ajudar minha família com seu fardo.",
  ui_story_5087_50870502_1_dialog_content = "Você pode usar Luminatics?",
  ui_story_5087_50870502_2_dialog_content = "E habilmente, além disso...",
  ui_story_5087_50870502_3_dialog_content = "Isso é dificilmente incomum aqui em Northland.",
  ui_story_5087_50870502_4_dialog_content = "Você estava tentando me proteger agora mesmo, não estava? Obrigado, por favor, aceite essas flores como um sinal de minha gratidão. Adeus!",
  ui_story_5087_50870502_5_dialog_content = "Espere, volte! Eu não posso simplesmente pegar isso de graça... Pelo menos me diga seu nome!",
  ui_story_5087_50870502_6_dialog_content = "Shaya. Meu nome é Shaya.",
  ui_story_5087_50870502_7_dialog_content = "Nikinis—",
  ui_story_5087_50870502_8_dialog_content = "Você está bem? Aquele monstro não te machucou, né? E com quem você estava falando agora mesmo?",
  ui_story_5087_50870502_9_dialog_content = "Estou bem, Nepolis. Conheci uma garotinha vendendo flores na floresta, e ela me deu um buquê por ajudá-la. Vê?",
  ui_story_5087_50870502_10_dialog_content = "Isso é ótimo, já que todas são as suas flores favoritas.",
  ui_story_5087_50870502_11_dialog_content = "Você nunca gostou de multidões, e sempre escapava do Palácio de Inverno durante os banquetes, mesmo aqueles feitos para você...",
  ui_story_5087_50870502_12_dialog_content = "Mas sempre, as pessoas que você ajudou te encontrariam e te dariam flores! Lindos buquês de narcisos brancos e lírios.",
  ui_story_5087_50870502_13_dialog_content = "Tenho certeza de que aquela garotinha também era... Hã?",
  ui_story_5087_50870502_14_dialog_content = "Este buquê só tem narcisos brancos nele...",
  ui_story_5087_50870502_15_dialog_content = "!",
  ui_story_5087_50870502_16_dialog_content = "Vamos lá, Nikinis. Vamos garantir que não há mais fragmentos de espelho por aqui antes de voltarmos para o Palácio Invernal.",
  ui_story_5087_50870502_17_dialog_content = "(É Nepolis... emburrada? Isso é estranho, eu acho que nunca vi esse lado dela.)",
  ui_story_5087_50870502_18_dialog_content = "(Vou colocar uma dessas flores no cabelo dela. Assim, o narciso branco e o lírio estarão juntos novamente.)",
  ui_story_5087_50870502_19_dialog_content = "Hum? Tem algo duro escondido dentro deste buquê...",
  ui_story_5087_50870502_20_dialog_content = "É esse espelho de mão!",
  ui_story_5087_50870502_21_dialog_content = "(Shaya fez isso de propósito? Ela enfiou este espelho no buquê porque me recusei a comprá-lo?)",
  ui_story_5087_50870502_22_dialog_content = "(Por que ela estava tão determinada a me dar isso?)",
  ui_story_5087_50870502_23_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870502_24_dialog_content = "(É ele de novo! A voz do Espelho de Northland! Ele pode aparecer em outros espelhos também?)",
  ui_story_5087_50870502_25_dialog_content = "(Isso é ruim, eu prometi a Nepólis que não iria perto de nenhum espelho suspeito...)",
  ui_story_5087_50870502_26_dialog_content = "Nikinis... Você pode me ouvir?",
  ui_story_5087_50870502_27_dialog_content = "...",
  ui_story_5087_50870502_28_dialog_content = "Sim, mas quem é você? Por que você continua aparecendo dentro dos espelhos?",
  ui_story_5087_50870502_29_dialog_content = "Excelente, o espelho finalmente chegou às suas mãos... Por favor... Não conte a ninguém sobre isso!",
  ui_story_5087_50870600_1_dialog_content = "<color=#e8d9bb>A noite cai, e uma nevasca uivante cobre o céu com neve. Até as sombras das chamas dentro da lareira parecem tremular com inquietação.</color>",
  ui_story_5087_50870600_2_dialog_content = "(Eu me pergunto como nossos pais estão enfrentando uma tempestade como esta... Certamente eles não ficariam ao ar livre em noites como esta, eu acho?)",
  ui_story_5087_50870600_3_dialog_content = "Finalmente terminei de relatar tudo para a rainha, Nikinis! Ela ficou realmente satisfeita com nossos resultados!",
  ui_story_5087_50870600_4_dialog_content = "Isso é maravilhoso. Agora podemos finalmente ir para casa e passar algum tempo com nossos pais.",
  ui_story_5087_50870600_5_dialog_content = "Ah... Certo...",
  ui_story_5087_50870600_6_dialog_content = "Nepolis! Nikinis! Oh, graças a Deus que você ainda não saiu!",
  ui_story_5087_50870600_7_dialog_content = "Acabou de chegar uma carta dos seus pais. Eles disseram que ainda estão cumprindo as ordens da rainha, então não poderão retornar por mais alguns dias.",
  ui_story_5087_50870600_8_dialog_content = "Em uma tempestade como esta, é melhor se você também não voltar agora. Não gostaria de ficar preso na neve, certo?",
  ui_story_5087_50870600_9_dialog_content = "M-Mas…",
  ui_story_5087_50870600_10_dialog_content = "Ele tem razão, Nikinis. Tentar navegar nesta nevasca à noite seria muito perigoso.",
  ui_story_5087_50870600_11_dialog_content = "Além disso, nossos pais nem estão em casa agora. Vamos apenas passar a noite em algum lugar por perto, certo?",
  ui_story_5087_50870600_12_dialog_content = "Se você diz...",
  ui_story_5087_50870600_13_dialog_content = "(Não me lembro de ver nossos pais no Palácio de Inverno antes... Isso poderia ser uma consequência da minha doença?)",
  ui_story_5087_50870600_14_dialog_content = "(Se eles estivessem trabalhando para a rainha, certamente Nepolis e eu os teríamos visto no palácio, certo?)",
  ui_story_5087_50870600_15_dialog_content = "(Mas eles realmente estão cumprindo as ordens da rainha? Quando eles começaram a fazer isso? Por que eu não me lembro de nada disso?)",
  ui_story_5087_50870600_16_dialog_content = "(A única coisa que consigo lembrar claramente é deles nos levando ao Palácio Invernal para tratamento.)",
  ui_story_5087_50870600_17_dialog_content = "(Depois disso, eu mal conseguia lembrar dos rostos deles...)",
  ui_story_5087_50870600_18_dialog_content = "(Poderia ser que minha doença afetou minhas memórias de alguma forma?)",
  ui_story_5087_50870600_19_dialog_content = "(Mesmo que eu não me lembre de nada disso, Nepolis e aquele mensageiro estão falando sobre isso como se fosse completamente normal. Quase parece que...)",
  ui_story_5087_50870600_20_dialog_content = "(Este mundo está envolto em uma camada de ilusão.)",
  ui_story_5087_50870600_21_dialog_content = "(Não... Devo estar imaginando coisas. Minha irmã é real, sem dúvida.)",
  ui_story_5087_50870600_22_dialog_content = "... Ah!",
  ui_story_5087_50870600_23_dialog_content = "O que é, Nepolis?",
  ui_story_5087_50870600_24_dialog_content = "Meu cabelo! Ele ficou preso em um dos galhos da árvore! Ajude-me, Nikinis!",
  ui_story_5087_50870600_25_dialog_content = "Sinceramente... Como você conseguiu prender isso em um galho? Pare de se contorcer antes que se machuque!",
  ui_story_5087_50870600_26_dialog_content = "É porque eu vi um pequeno esquilo fofo agora há pouco. Eu caminhei para dar uma olhada mais de perto, mas então...",
  ui_story_5087_50870600_27_dialog_content = "Você conseguiu fazer algumas coisas incríveis quando eu não estava prestando atenção, sabia?",
  ui_story_5087_50870600_28_dialog_content = "Você é um para falar, Nikinis. Você tem descoberto todos os tipos de poderes e emoções ultimamente, tudo sem que eu perceba...",
  ui_story_5087_50870600_29_dialog_content = "Costumávamos ser um e o mesmo, lembra? Nossos corações e almas estavam conectados, e compartilhávamos tudo, desde nossa aparência e talentos até nossos gostos e desgostos.",
  ui_story_5087_50870600_30_dialog_content = "Ver você se tornar lentamente outra pessoa às vezes me faz sentir tão sozinho...",
  ui_story_5087_50870600_31_dialog_content = "Veja o buquê que você recebeu - narcisos estão atados de perto com rosas amarelas e não-me-esqueças, mas sem nenhum lírio...",
  ui_story_5087_50870600_32_dialog_content = "Nepolis... Do que diabos você está falando? Não existe outro par de irmãos no mundo mais parecido do que nós dois! Quando nos tornamos \"diferentes\" para você?",
  ui_story_5087_50870600_33_dialog_content = "Prometi nunca mais me aproximar daquele espelho novamente, então por favor, não se preocupe comigo, ok?",
  ui_story_5087_50870600_34_dialog_content = "... Pronto! Seu cabelo está desembaraçado agora. Saia de debaixo daquela árvore.",
  ui_story_5087_50870600_35_dialog_content = "Doce, doce liberdade!",
  ui_story_5087_50870600_36_dialog_content = "... Obrigado, Nikinis. Sem você, eu não sei o que faria.",
  ui_story_5087_50870600_37_dialog_content = "Então, apenas pare de dizer coisas como \"Não sou útil para minha irmã...\"",
  ui_story_5087_50870600_38_dialog_content = "Ter você ao meu lado é a maior bênção que eu poderia pedir.",
  ui_story_5087_50870600_39_dialog_content = "(Nepolis é real, e eu também. Não há dúvida sobre isso.)",
  ui_story_5087_50870600_40_dialog_content = "(É por isso... Eu tenho que destruir este espelho misterioso.)",
  ui_story_5087_50870600_41_dialog_content = "Nikinis... É você?",
  ui_story_5087_50870600_42_dialog_content = "(... Ele voltou de novo!)",
  ui_story_5087_50870600_43_dialog_content = "Por favor, não fale mais comigo. Não quero que minha irmã continue sofrendo assim!",
  ui_story_5087_50870600_44_dialog_content = "Apenas me escute, Nikinis! Você tem que ir... e encontrar... só então...",
  ui_story_5087_50870600_45_dialog_content = "Ir aonde? O que eu supostamente devo encontrar?",
  ui_story_5087_50870600_46_dialog_content = "Quem é você e por que continua falando comigo através dos espelhos?",
  ui_story_5087_50870600_47_dialog_content = "Eu sou... Você está em um... Só por... você pode...",
  ui_story_5087_50870600_48_dialog_content = "... Eu não consigo entender nada do que você está dizendo. Sua voz continua desaparecendo nos piores momentos!",
  ui_story_5087_50870600_49_dialog_content = "É aquela coisa! Continua interferindo conosco! Mesmo depois de quebrar o... nunca parou. Ainda está bloqueando... Argh!",
  ui_story_5087_50870600_50_dialog_content = "\"Quebrando\"? Você está falando sobre o Espelho de Northland? Você sabe quem fez isso? Espere, como você sabe sobre o espelho estar quebrado?",
  ui_story_5087_50870600_51_dialog_content = "Poderia ser... que você foi quem roubou o Espelho de Northland?",
  ui_story_5087_50870600_52_dialog_content = "<color=#e8d9bb>Antes que a pessoa no espelho possa responder, a nevasca atinge ainda mais forte a cabana, fazendo as janelas tremerem em suas molduras.</color>",
  ui_story_5087_50870600_53_dialog_content = "<color=#e8d9bb>Nikinis abaixa a cabeça mais uma vez. O espelho em suas mãos reflete nada além das chamas cintilantes da lareira e a neve rodopiante lá fora.</color>",
  ui_story_5087_50870700_1_dialog_content = "<color=#e8d9bb>A neve continua a cair enquanto nuvens sombrias pairam sobre Northland, sua aparência escura e solene reflete diretamente o humor de Nikinis.</color>",
  ui_story_5087_50870700_2_dialog_content = "<color=#e8d9bb>Um lar inalcançável, um mistério insolúvel e uma memória incerta... Todas essas coisas pesam muito em seu coração.</color>",
  ui_story_5087_50870700_3_dialog_content = "<color=#e8d9bb>Seu único vislumbre de esperança é o espelho em suas mãos, que ela quase destruiu.</color>",
  ui_story_5087_50870700_4_dialog_content = "(A pessoa no espelho não parece que vai voltar tão cedo...)",
  ui_story_5087_50870700_5_dialog_content = "(Alguém realmente está interferindo em nossa comunicação? Talvez seja a pessoa que quebrou o espelho em primeiro lugar.)",
  ui_story_5087_50870700_6_dialog_content = "(A pessoa no espelho quer que eu faça algo... Mas por quê? Eles estão lutando com quem quebrou o espelho? As perguntas nunca parecem terminar...)",
  ui_story_5087_50870700_7_dialog_content = "Nikinis! Estamos em apuros!",
  ui_story_5087_50870700_8_dialog_content = "O-O que é?",
  ui_story_5087_50870700_9_dialog_content = "Hã? Por que você parece tão perturbado? Não me diga que você recebeu uma carta de amor ou algo assim.",
  ui_story_5087_50870700_10_dialog_content = "De jeito nenhum! Mesmo que eu fizesse, não esconderia de você-",
  ui_story_5087_50870700_11_dialog_content = "Eu nunca deixaria você se preocupar com algo assim, Nepolis. Confie em mim.",
  ui_story_5087_50870700_12_dialog_content = "... Você não precisa se defender assim, sabe? Suas cartas de amor são seus próprios negócios, afinal.",
  ui_story_5087_50870700_13_dialog_content = "Não há carta de amor!",
  ui_story_5087_50870700_14_dialog_content = "O-Ok, eu acredito em você! Agora apenas me ouça, algo realmente grande acabou de acontecer—",
  ui_story_5087_50870700_15_dialog_content = "A rainha acabou de publicar um retrato do ladrão do espelho!",
  ui_story_5087_50870700_16_dialog_content = "Quê? Onde?",
  ui_story_5087_50870700_17_dialog_content = "Oh? Eu não esperava que você estivesse tão preocupado com isso. Venha comigo.",
  ui_story_5087_50870700_18_dialog_content = "Queen Bethlehem descobriu a identidade do ladrão e postou um retrato dele para todos verem.",
  ui_story_5087_50870700_19_dialog_content = "A partir de hoje, as fronteiras de Northland serão fechadas, e suas forças estarão focadas na captura do ladrão. Todos os residentes de Northland são incentivados a relatar qualquer atividade suspeita imediatamente!",
  ui_story_5087_50870700_20_dialog_content = "Estão fechando as fronteiras? Sua Majestade raramente mobiliza o reino assim...",
  ui_story_5087_50870700_21_dialog_content = "Você não viu o que aconteceu esta manhã? O Palácio de Inverno praticamente enviou um exército para caçar este ladrão!",
  ui_story_5087_50870700_22_dialog_content = "Faz sentido para mim. Afinal, não é qualquer um que consegue se infiltrar no cofre do tesouro do Palácio de Inverno.",
  ui_story_5087_50870700_23_dialog_content = "Até mesmo uma única peça dessas relíquias é poderosa o suficiente para destruir cem vilas. A rainha está fazendo isso apenas por nós.",
  ui_story_5087_50870700_24_dialog_content = "Dê uma olhada neste retrato - aparentemente o ladrão é uma garotinha! Como uma criança conseguiu invadir o Palácio de Inverno?",
  ui_story_5087_50870700_25_dialog_content = "(Uma garotinha? Não me diga...)",
  ui_story_5087_50870700_26_dialog_content = "Perdoe-me! Passando—",
  ui_story_5087_50870700_27_dialog_content = "(Eu sabia... Era ela!)",
  ui_story_5087_50870700_28_dialog_content = "Você também está surpreso, não está Nikinis? Afinal, o ladrão mais procurado de Northland é apenas uma garotinha fofa...",
  ui_story_5087_50870700_29_dialog_content = "E-Eu tenho que ir, Nepolis!",
  ui_story_5087_50870700_30_dialog_content = "Hã? Espere, Nikinis, a rainha nos incumbiu de outra missão—",
  ui_story_5087_50870700_31_dialog_content = "Ei! Você tá aí? Por favor, diga algo!",
  ui_story_5087_50870700_32_dialog_content = "(Sem resposta... Como eu fiz a pessoa no espelho aparecer da última vez? Isso mesmo! Foi quando eu pensei em usar Luminatics para destruí-lo!)",
  ui_story_5087_50870700_33_dialog_content = "(Vou tentar infundir o espelho com Lumina primeiro...)",
  ui_story_5087_50870700_34_dialog_content = "Nikinis!",
  ui_story_5087_50870700_35_dialog_content = "Você está aqui! Me diga, está trabalhando com uma garotinha chamada Shaya?",
  ui_story_5087_50870700_36_dialog_content = "Vocês dois foram os que roubaram o Espelho de Northland, não foram?",
  ui_story_5087_50870700_37_dialog_content = "... Isso mesmo. Shaya é na verdade... Porque ela... e entrou... por conta própria...",
  ui_story_5087_50870700_38_dialog_content = "O Espelho Northland é a passagem que preparamos para você... mas foi quebrado por...",
  ui_story_5087_50870700_39_dialog_content = "Deve ser restaurado primeiro... é por isso que precisamos da sua ajuda.",
  ui_story_5087_50870700_40_dialog_content = "Nós enviamos Shaya para entregar este espelho a você, para que pudéssemos nos comunicar.",
  ui_story_5087_50870700_41_dialog_content = "Do que você está falando? Me diga o que você está planejando!",
  ui_story_5087_50870700_42_dialog_content = "Não posso te responder agora. Sempre que tento te dizer algo... bloqueado.",
  ui_story_5087_50870700_43_dialog_content = "Encontre a Shaya, e ela te dirá tudo... Só ela pode te ajudar agora!",
  ui_story_5087_50870700_44_dialog_content = "<color=#e8d9bb>A pessoa no espelho desaparece com um flash.</color>",
  ui_story_5087_50870700_45_dialog_content = "(O julgamento de Sua Majestade não estava errado afinal... A que roubou o Espelho do Norte foi a Shaya.)",
  ui_story_5087_50870700_46_dialog_content = "(Não só isso, ela e a pessoa no espelho estão tramando algo juntas.)",
  ui_story_5087_50870700_47_dialog_content = "(Mas por quê? Eu não senti nenhuma animosidade da Shaya ou deste espelho...)",
  ui_story_5087_50870700_48_dialog_content = "...",
  ui_story_5087_50870700_49_dialog_content = "(Vou manter o espelho fora de vista por enquanto. Nepólis voltará a qualquer segundo.)",
  ui_story_5087_50870700_50_dialog_content = "(Não acredito que estou guardando um segredo tão grande dela... Ao confiar no espelho, estou colocando mais distância entre nós?)",
  ui_story_5087_50870700_51_dialog_content = "Nikinis! Como você pôde fugir assim sozinho?",
  ui_story_5087_50870700_52_dialog_content = "... Desculpe.",
  ui_story_5087_50870700_53_dialog_content = "A rainha nos ordenou capturar o ladrão do espelho! Não há tempo a perder, então pegue seu casaco e botas—",
  ui_story_5087_50870700_54_dialog_content = "Oh! Desculpa, estarei aí agora mesmo! Obrigado por me avisar... Desculpe por ter fugido agora há pouco.",
  ui_story_5087_50870700_55_dialog_content = "... Por que você está pedindo tantas desculpas? Somos irmãs, lembra?",
  ui_story_5087_50870700_56_dialog_content = "Você é a pessoa mais importante na minha vida. Não importa o que aconteça, isso nunca vai mudar.",
  ui_story_5087_50870800_1_dialog_content = "Vou verificar lá, Nepolis.",
  ui_story_5087_50870800_2_dialog_content = "Então vou olhar por aqui. Fique atento.",
  ui_story_5087_50870800_3_dialog_content = "Eu vou ficar bem. Além disso, sei que você virá ao meu resgate assim que perceber que estou em apuros.",
  ui_story_5087_50870800_4_dialog_content = "Como gêmeos, estamos conectados em mente e alma, lembra?",
  ui_story_5087_50870800_5_dialog_content = "...",
  ui_story_5087_50870800_6_dialog_content = "(Este lugar deve ser seguro o suficiente.)",
  ui_story_5087_50870800_7_dialog_content = "Ei, você tá aí?",
  ui_story_5087_50870800_8_dialog_content = "O que é, Nikinis? Você conseguiu encontrar a Shaya?",
  ui_story_5087_50870800_9_dialog_content = "Ainda não, não. Minha irmã e eu estamos procurando por ela neste momento, junto com o resto do reino.",
  ui_story_5087_50870800_10_dialog_content = "Não consigo me lembrar de um momento em que todo o Northland foi mobilizado para caçar um único ladrão. Afinal, algo neste mundo não parece certo...",
  ui_story_5087_50870800_11_dialog_content = "Isso é porque você é... Não se preocupe com a Shaya, no entanto. Afinal, ela é... Pessoas comuns não deveriam representar uma ameaça para ela.",
  ui_story_5087_50870800_12_dialog_content = "Escute-me, espelho! Eu...",
  ui_story_5087_50870800_13_dialog_content = "Quero contar tudo o que sei sobre você e Shaya para minha irmã...",
  ui_story_5087_50870800_14_dialog_content = "Huh? Eu... Eu não sei se isso é uma boa ideia...",
  ui_story_5087_50870800_15_dialog_content = "Minha irmã e eu somos uma e a mesma.",
  ui_story_5087_50870800_16_dialog_content = "Uhh?",
  ui_story_5087_50870800_17_dialog_content = "Desde que viemos ao mundo, sempre estivemos juntos. Como duas flores plantadas uma ao lado da outra, crescemos e florescemos exatamente da mesma maneira.",
  ui_story_5087_50870800_18_dialog_content = "Não consigo explicar por quê, mas sei que você e Shaya não são pessoas ruins. Talvez seja apenas minha intuição...",
  ui_story_5087_50870800_19_dialog_content = "E se for, minha irmã terá a mesma intuição que a minha. Não importa o que você esteja planejando, ela não vai se colocar no seu caminho.",
  ui_story_5087_50870800_20_dialog_content = "Na verdade, ela vai ajudá-lo.",
  ui_story_5087_50870800_21_dialog_content = "... Você tem tanta certeza assim?",
  ui_story_5087_50870800_22_dialog_content = "Positivo. Isso porque já estou considerando o mesmo.",
  ui_story_5087_50870800_23_dialog_content = "Só preciso olhar para o meu próprio coração para saber qual será a escolha da minha irmã.",
  ui_story_5087_50870800_24_dialog_content = "... Entendo.",
  ui_story_5087_50870800_25_dialog_content = "Eu tenho mais um pedido. Queen Bethlehem é quem ordenou a captura de Shaya, o que significa que ela deve saber de algo.",
  ui_story_5087_50870800_26_dialog_content = "Seria certo se eu também contasse a ela sobre—",
  ui_story_5087_50870800_27_dialog_content = "Nunca!",
  ui_story_5087_50870800_28_dialog_content = "?",
  ui_story_5087_50870800_29_dialog_content = "Isso \"Queen Bethlehem\" é... Ela não é... então você não pode...",
  ui_story_5087_50870800_30_dialog_content = "Não consigo ouvir o que você está dizendo. Acho que a interferência está piorando.",
  ui_story_5087_50870800_31_dialog_content = "Urgh! Como eu deveria te dizer... Não acredite... Falso!",
  ui_story_5087_50870800_32_dialog_content = "O que é falso? A carta daquele mensageiro? A história sobre meus pais? Minhas memórias?",
  ui_story_5087_50870800_33_dialog_content = "Ou poderia ser... a rainha?",
  ui_story_5087_50870800_34_dialog_content = "Muito mal!",
  ui_story_5087_50870800_35_dialog_content = "Sua Majestade é uma farsa?",
  ui_story_5087_50870800_36_dialog_content = "Sim! É verdade! Ela... O objetivo dela é...",
  ui_story_5087_50870800_37_dialog_content = "... Pare aí mesmo!",
  ui_story_5087_50870800_38_dialog_content = "?",
  ui_story_5087_50870800_39_dialog_content = "Ugh!",
  ui_story_5087_50870800_40_dialog_content = "Finalmente te peguei! Vamos ver você fugir agora!",
  ui_story_5087_50870800_41_dialog_content = "O que é, Nepolis? Ah! É você... Shaya...",
  ui_story_5087_50870800_42_dialog_content = "Eu peguei essa pequena ladra sorrateira te perseguindo das árvores. Ela definitivamente estava tramando algo sinistro!",
  ui_story_5087_50870800_43_dialog_content = "Mas não se preocupe, eu a peguei antes que ela pudesse fazer seu movimento! Você está seguro agora!",
  ui_story_5087_50870800_44_dialog_content = "...",
  ui_story_5087_50870800_45_dialog_content = "Nikinis... Me ajude...",
  ui_story_5087_50870800_46_dialog_content = "O quê? Vo-Vocês se conhecem? Quando isso aconteceu? E por que eu não fui informado sobre isso?",
  ui_story_5087_50870800_47_dialog_content = "Nepolis... Sinto muito.",
  ui_story_5087_50870800_48_dialog_content = "Ah! Eu não estava te culpando—",
  ui_story_5087_50870800_49_dialog_content = "Mas não se preocupe, eu vou te contar tudo agora. Eu não vou esconder nada de você nunca mais, eu prometo.",
  ui_story_5087_50870800_50_dialog_content = "Depois disso... Vou precisar da sua sabedoria.",
  ui_story_5087_50870900_1_dialog_content = "Queen Bethlehem é um impostor?",
  ui_story_5087_50870900_2_dialog_content = "Sim. Ela não é nada além de uma ilusão de sombras, é por isso que sua reação é tão agressiva.",
  ui_story_5087_50870900_3_dialog_content = "Mobilizar um reino inteiro para prender um único ladrão... é um uso extremamente ineficiente de seu poder.",
  ui_story_5087_50870900_4_dialog_content = "A verdadeira rainha teria pensado em algo muito mais engenhoso.",
  ui_story_5087_50870900_5_dialog_content = "(Mesmo após encontrá-la pela segunda vez, ainda acho que há algo único sobre a Shaya.)",
  ui_story_5087_50870900_6_dialog_content = "(Apesar de ser uma garota tão jovem, ela tem um ar de retidão e não tem escrúpulos em criticar a rainha.)",
  ui_story_5087_50870900_7_dialog_content = "É verdade que os métodos de Sua Majestade têm sido um pouco diferentes ultimamente, mas isso mal é motivo para suspeitá-la...",
  ui_story_5087_50870900_8_dialog_content = "Se o que você disse é verdade, Shaya, então onde está a verdadeira rainha?",
  ui_story_5087_50870900_9_dialog_content = "... Em geral, Bethlehem tende a passar seu tempo em um mundo diferente - o mundo do outro lado do Espelho do Northland.",
  ui_story_5087_50870900_10_dialog_content = "... Você está dizendo que há um mundo inteiramente diferente atrás do Espelho de Northland?",
  ui_story_5087_50870900_11_dialog_content = "Isso significa que seu motivo para roubar o espelho era viajar para este outro mundo e encontrar o verdadeiro Queen Bethlehem?",
  ui_story_5087_50870900_12_dialog_content = "Seu raciocínio está no caminho certo... É verdade, eu preciso ir para lá.",
  ui_story_5087_50870900_13_dialog_content = "O Espelho de Northland é a passagem perfeita para viajar entre ambos os mundos.",
  ui_story_5087_50870900_14_dialog_content = "Mas agora que está quebrado, precisa ser consertado antes que eu possa fazer isso.",
  ui_story_5087_50870900_15_dialog_content = "Nikinis, você tem uma poderosa afinidade com o Espelho de Northland. Para restaurá-lo ao seu estado original, preciso de sua ajuda.",
  ui_story_5087_50870900_16_dialog_content = "Você está disposto a me ajudar? Naturalmente, eu também estaria disposto a ajudar vocês dois.",
  ui_story_5087_50870900_17_dialog_content = "O que está no espelho pode servir como seu guia. Ele também existe no outro mundo, e seu objetivo não é diferente do meu.",
  ui_story_5087_50870900_18_dialog_content = "...",
  ui_story_5087_50870900_19_dialog_content = "O que você acha, Nepólis? Eu sei que você não quer que eu chegue perto daquele espelho.",
  ui_story_5087_50870900_20_dialog_content = "Mas você quer fazer isso, não quer?",
  ui_story_5087_50870900_21_dialog_content = "(Eu...)",
  ui_story_5087_50870900_22_dialog_content = "... Me desculpe, Nikinis. Parece que meu ciúme fez você se preocupar.",
  ui_story_5087_50870900_23_dialog_content = "Posso dizer que você tem pensado em mim e nos meus sentimentos nos últimos dias...",
  ui_story_5087_50870900_24_dialog_content = "Mesmo sendo o mais velho, mal estou agindo como tal.",
  ui_story_5087_50870900_25_dialog_content = "Isso não é verdade! Você e eu pensamos exatamente igual. Tudo que eu quero é estar com você em mente e alma, como sempre...",
  ui_story_5087_50870900_26_dialog_content = "... É o que eu mais quero no mundo inteiro!",
  ui_story_5087_50870900_27_dialog_content = "Mas isso não me dá o direito de tirar suas asas.",
  ui_story_5087_50870900_28_dialog_content = "!",
  ui_story_5087_50870900_29_dialog_content = "...",
  ui_story_5087_50870900_30_dialog_content = "A verdade é, estou tendo um tempo muito difícil para acreditar em tudo que você acabou de nos contar, Shaya.",
  ui_story_5087_50870900_31_dialog_content = "... Entendo.",
  ui_story_5087_50870900_32_dialog_content = "Mas minha irmã sempre deu muita importância para aquele espelho.",
  ui_story_5087_50870900_33_dialog_content = "Depois de ouvir a história da rainha sobre como fomos curados, estou convencido de que Nikinis e o espelho compartilham um destino inextricável.",
  ui_story_5087_50870900_34_dialog_content = "Eu me sentia solitário porque apenas minha irmã foi escolhida, e então comecei a agir por inveja...",
  ui_story_5087_50870900_35_dialog_content = "Foi errado da minha parte fazer isso. Como a irmã mais velha, eu deveria estar cuidando dela e ajudando-a a crescer.",
  ui_story_5087_50870900_36_dialog_content = "Népolis...",
  ui_story_5087_50870900_37_dialog_content = "... Você tem uma alma incrível, Nepolis.",
  ui_story_5087_50870900_38_dialog_content = "Talvez eu tenha subestimado você o tempo todo.",
  ui_story_5087_50870900_39_dialog_content = "Então, Shaya—",
  ui_story_5087_50870900_40_dialog_content = "Apenas nos diga o que precisamos fazer para ajudá-lo a restaurar o Espelho de Northland!",
  ui_story_5087_50871000_1_dialog_content = "...",
  ui_story_5087_50871000_2_dialog_content = "...",
  ui_story_5087_50871000_3_dialog_content = "Hmm... Uma vez que cruzarmos esta montanha, devemos chegar ao Palácio Invernal.",
  ui_story_5087_50871000_4_dialog_content = "...",
  ui_story_5087_50871000_5_dialog_content = "...",
  ui_story_5087_50871000_6_dialog_content = "Não podemos continuar caminhando em silêncio! Shaya, eu sei que você está muito insatisfeita com a falsa rainha agora—",
  ui_story_5087_50871000_7_dialog_content = "Estou extremamente insatisfeito, na verdade. Ela mobilizou todos os soldados do reino para caçar um ladrão!",
  ui_story_5087_50871000_8_dialog_content = "Nepolis, eu sei que você ainda não está convencido—",
  ui_story_5087_50871000_9_dialog_content = "É claro que não estou convencido!",
  ui_story_5087_50871000_10_dialog_content = "É uma coisa restaurar o Espelho de Northland, ou se infiltrar no cofre do tesouro do Palácio de Inverno...",
  ui_story_5087_50871000_11_dialog_content = "Mas \"como unir nossas forças e derrotar a rainha se ela nos descobrir\"? Como ousa incluir isso no seu plano!",
  ui_story_5087_50871000_12_dialog_content = "Você até fez um desenho para isso!",
  ui_story_5087_50871000_13_dialog_content = "Como você conhece tão bem as fraquezas da rainha, Shaya? Tem certeza de que não está tramando mais nada?",
  ui_story_5087_50871000_14_dialog_content = "... Agora entendo a dor de não conseguir dizer a verdade.",
  ui_story_5087_50871000_15_dialog_content = "Nikinis! Você não se lembra do risco que Sua Majestade correu para salvar nossas vidas?",
  ui_story_5087_50871000_16_dialog_content = "(Eu...)",
  ui_story_5087_50871000_17_dialog_content = "Como você pode acreditar tão facilmente em cada palavra que essa garota diz sobre nossa rainha ser uma impostora?",
  ui_story_5087_50871000_18_dialog_content = "Nepolis, eu te elogio por ser tão leal a Bethlehem—",
  ui_story_5087_50871000_19_dialog_content = "Pare de se referir à rainha apenas pelo nome dela!",
  ui_story_5087_50871000_20_dialog_content = "Mas até mesmo o verdadeiro Bethlehem ficaria perplexo com a sua teimosia agora.",
  ui_story_5087_50871000_21_dialog_content = "Como ousa dizer isso sobre Sua Majestade! Uma rainha digna e nobre como ela nunca...",
  ui_story_5087_50871000_22_dialog_content = "Ela faria. Confie em mim.",
  ui_story_5087_50871000_23_dialog_content = "Vocês dois...",
  ui_story_5087_50871000_24_dialog_content = "Também não sei por que você está com tanta pressa, Nikinis.",
  ui_story_5087_50871000_25_dialog_content = "Infiltrar o cofre do tesouro requer planejamento e investigação cuidadosos. Além disso, o Espelho de Northland não vai a lugar nenhum.",
  ui_story_5087_50871000_26_dialog_content = "Por que insiste em invadir lá hoje? E se a rainha nos encontrar, você realmente está preparado para lutar contra ela?",
  ui_story_5087_50871000_27_dialog_content = "Aquilo não é sua rainha.",
  ui_story_5087_50871000_28_dialog_content = "Você é o único que diz isso.",
  ui_story_5087_50871000_29_dialog_content = "A maioria dos soldados do Palácio Invernal está vasculhando o país atrás de mim agora. Não teremos outra chance como essa para invadir o cofre.",
  ui_story_5087_50871000_30_dialog_content = "Então você sabe que também estamos \"invadindo\", não sabe?",
  ui_story_5087_50871000_31_dialog_content = "Nepolis! Shaya! Pare com essa briga agora mesmo!",
  ui_story_5087_50871000_32_dialog_content = "É verdade, estou com pressa para fazer isso. Mas Nepolis, você precisa entender que há algo terrivelmente errado com este mundo agora...",
  ui_story_5087_50871000_33_dialog_content = "...",
  ui_story_5087_50871000_34_dialog_content = "O que exatamente há de errado com isso?",
  ui_story_5087_50871000_35_dialog_content = "Muitas coisas... Por exemplo, quando nossos pais começaram a trabalhar para o Palácio de Inverno? Você e todos os outros parecem saber disso, mas eu não me lembro disso de jeito nenhum...",
  ui_story_5087_50871000_36_dialog_content = "O quê? Isso poderia ser uma sequela da sua doença? Você está se sentindo mal de novo?",
  ui_story_5087_50871000_37_dialog_content = "(Eu...)",
  ui_story_5087_50871000_38_dialog_content = "(O que devo fazer? Pela primeira vez na minha vida... Não sei como dizer à minha irmã o que estou pensando.)",
  ui_story_5087_50871000_39_dialog_content = "(Ela parece tão preocupada comigo. Será que eu estou sendo muito teimoso sobre isso?)",
  ui_story_5087_50871000_40_dialog_content = "... Estou apenas aliviado que você está bem. Eu vou... fazer o reconhecimento à frente por agora.",
  ui_story_5087_50871000_41_dialog_content = "Nenhum de vocês está errado, então por favor não se incomodem. É só que apenas você é capaz de sentir certas coisas.",
  ui_story_5087_50871000_42_dialog_content = "Mas por quê... Por que eu sou o único que pode senti-los?",
  ui_story_5087_50871000_43_dialog_content = "Minha irmã e eu sempre fomos iguais. Quando foi que começamos... a ter essas diferenças?",
  ui_story_5087_50871000_44_dialog_content = "Embora ambos sejam tão puros e brancos quanto a neve, um lírio e um narciso branco sempre serão duas flores diferentes. Além disso...",
  ui_story_5087_50871000_45_dialog_content = "...",
  ui_story_5087_50871000_46_dialog_content = "Por favor, me diga, Shaya! É só minha imaginação, ou realmente tem algo errado com este mundo?",
  ui_story_5087_50871000_47_dialog_content = "Além da rainha ser falsa, há algo mais que você não está me contando?",
  ui_story_5087_50871000_48_dialog_content = "... Há.",
  ui_story_5087_50871000_49_dialog_content = "!",
  ui_story_5087_50871000_50_dialog_content = "Mas seria imprudente da minha parte te dizer agora.",
  ui_story_5087_50871000_51_dialog_content = "Uma vez que chegarmos ao Palácio Invernal e restaurarmos o espelho, tudo será esclarecido.",
  ui_story_5087_50871000_52_dialog_content = "Você... Você não tem uma irmã, tem?",
  ui_story_5087_50871000_53_dialog_content = "... Eu sim.",
  ui_story_5087_50871000_54_dialog_content = "Você faz?",
  ui_story_5087_50871000_55_dialog_content = "Embora mesmo pelos padrões mais generosos, está longe de ser considerado um relacionamento amigável.",
  ui_story_5087_50871000_56_dialog_content = "Então, eu realmente invejo Nepolis e você.",
  ui_story_5087_50871000_57_dialog_content = "... Eu quero proteger vocês dois, mesmo que seja apenas por mais um segundo.",
  ui_story_5087_50871000_58_dialog_content = "Você entendeu errado, Shaya.",
  ui_story_5087_50871000_59_dialog_content = "Uhh?",
  ui_story_5087_50871000_60_dialog_content = "Mesmo que minha irmã e eu tenhamos nascido com uma conexão telepática que nos concedeu consciência dos pensamentos do outro—",
  ui_story_5087_50871000_61_dialog_content = "Ainda lutamos. Você mesmo viu.",
  ui_story_5087_50871000_62_dialog_content = "!",
  ui_story_5087_50871000_63_dialog_content = "Mas isso é apenas temporário. É apenas um pouco de atrito que surge de uma diferença de sentimentos e experiências.",
  ui_story_5087_50871000_64_dialog_content = "O fato de você invejar o relacionamento que temos é prova de que você não desistiu de sua própria relação fraterna...",
  ui_story_5087_50871000_65_dialog_content = "Você ainda sonha em fazer as pazes com sua irmã.",
  ui_story_5087_50871000_66_dialog_content = "Enquanto você não desistir, um dia, vocês vão se entender... pelo menos é no que eu acredito.",
  ui_story_5087_50871000_67_dialog_content = "... Obrigado, Nikinis. Vou manter isso em mente.",
  ui_story_5087_50871000_68_dialog_content = "Nepolis se recusa a fazer um movimento contra a falsa rainha, então vamos nos separar uma vez que estivermos dentro do Palácio Invernal.",
  ui_story_5087_50871000_69_dialog_content = "Vou descobrir como lidar com a rainha. Você apenas siga direto para o cofre do tesouro com sua irmã.",
  ui_story_5087_50871000_70_dialog_content = "Não posso deixar você fazer isso! Sua Majestade é muito forte—",
  ui_story_5087_50871000_71_dialog_content = "Não, é melhor assim. Vamos nos destacar se ficarmos juntos.",
  ui_story_5087_50871000_72_dialog_content = "Com a conexão que vocês dois compartilham, vocês formam um par muito mais eficiente quando não estão me arrastando junto.",
  ui_story_5087_50871000_73_dialog_content = "Vou manter a rainha ocupada em segredo e cobrir você. É mais fácil fazer isso sozinho.",
  ui_story_5087_50871000_74_dialog_content = "Procure respostas daquele no espelho se encontrar algum problema durante a operação.",
  ui_story_5087_50871000_75_dialog_content = "... Ele é meu companheiro de maior confiança, e ele será seu guia no Palácio de Inverno.",
  ui_story_5087_50871101_1_dialog_content = "... Shaya foi à nossa frente e entrou sorrateiramente no Palácio Invernal. Ela mencionou algo sobre uma passagem secreta que só ela poderia entrar.",
  ui_story_5087_50871101_2_dialog_content = "Hahaha! Ela está na forma de uma criança agora.",
  ui_story_5087_50871101_3_dialog_content = "?",
  ui_story_5087_50871101_4_dialog_content = "Agora, é a sua vez. A segurança é sempre rigorosa na entrada...",
  ui_story_5087_50871101_5_dialog_content = "Mas você está sempre entrando e saindo do Palácio Invernal, então não é um problema, certo?",
  ui_story_5087_50871101_6_dialog_content = "...",
  ui_story_5087_50871101_7_dialog_content = "Acho que sim!",
  ui_story_5087_50871101_8_dialog_content = "Alto lá.",
  ui_story_5087_50871101_9_dialog_content = "Olá, eu sou Nikinis, e isso é Nepolis. Temos negócios no Palácio de Inverno—",
  ui_story_5087_50871101_10_dialog_content = "A entrada é proibida ao público até que o ladrão do espelho seja capturado.",
  ui_story_5087_50871101_11_dialog_content = "(... O quê?)",
  ui_story_5087_50871101_12_dialog_content = "Não somos qualquer um. Encontramos o Espelho de Northland roubado.",
  ui_story_5087_50871101_13_dialog_content = "Estamos sob as ordens de Sua Majestade para rastrear o ladrão, e acabamos de descobrir uma pista que requer verificação cruzada na biblioteca do palácio.",
  ui_story_5087_50871101_14_dialog_content = "Poderia nos deixar passar? Todos nós estamos a serviço de Sua Majestade aqui.",
  ui_story_5087_50871101_15_dialog_content = "Ah... Hum...",
  ui_story_5087_50871101_16_dialog_content = "Sua ajuda será recompensada, é claro. Eu vou visitar com o fino chá concedido por Sua Majestade, e podemos apreciá-lo juntos!",
  ui_story_5087_50871101_17_dialog_content = "Sério? Ahem... Pensando bem, você está intimamente relacionado ao roubo e deve ser permitida a entrada.",
  ui_story_5087_50871101_18_dialog_content = "Você pode passar.",
  ui_story_5087_50871101_19_dialog_content = "(Isso funcionou!)",
  ui_story_5087_50871101_20_dialog_content = "... Vire à direita em frente, continue reto, depois desça as escadas.",
  ui_story_5087_50871101_21_dialog_content = "Mantenha seus olhos abertos. Zarya costuma sentar-se na janela da baía para apreciar a vista. Não deixe que ela te pegue.",
  ui_story_5087_50871101_22_dialog_content = "Zarya? Quem? Bem, eu olhei, e não há ninguém lá.",
  ui_story_5087_50871101_23_dialog_content = "Zarya ainda não apareceu no outro mundo? Ah, eu falei demais... Ah! Abaixe-se! Os coelhos de Novio estão definitivamente se escondendo naquele pátio lá fora!",
  ui_story_5087_50871101_24_dialog_content = "Fique atento também ao descer as escadas. Quase fui enviado para seis pés abaixo por uma folha de gelo Noah deixada para trás...",
  ui_story_5087_50871101_25_dialog_content = "Sério, quem é você? Você está agindo de forma tão secreta, mas possui um conhecimento extenso sobre a estrutura e o pessoal do Palácio de Inverno... Tem certeza de que não é um espião?",
  ui_story_5087_50871101_26_dialog_content = "Confie em mim, eu sou uma boa pessoa!",
  ui_story_5087_50871101_27_dialog_content = "... Tudo será revelado assim que o espelho for reparado.",
  ui_story_5087_50871101_28_dialog_content = "... Hunf.",
  ui_story_5087_50871101_29_dialog_content = "Bem, já chegamos até aqui, então vamos apenas confiar nele e em Shaya.",
  ui_story_5087_50871101_30_dialog_content = "Falando nisso, não teríamos chegado aqui sem você. Se eu estivesse sozinho, nem teria conseguido entrar.",
  ui_story_5087_50871101_31_dialog_content = "Você está preocupado com meus sentimentos novamente, não está?",
  ui_story_5087_50871101_32_dialog_content = "Não, eu não sou!",
  ui_story_5087_50871101_33_dialog_content = "Posso sentir seus sentimentos, lembra?",
  ui_story_5087_50871101_34_dialog_content = "...",
  ui_story_5087_50871101_35_dialog_content = "Nikinis, lembra do distúrbio de memória que você mencionou? Tem certeza de que não é um efeito colateral da sua doença?",
  ui_story_5087_50871101_36_dialog_content = "Bem... Para ser honesto, eu não sei, mas algo me diz que há mais do que aparenta.",
  ui_story_5087_50871101_37_dialog_content = "Bem então... Vamos resolver todos os mistérios. Não importa o que você faça, eu sempre estarei ao seu lado.",
  ui_story_5087_50871101_38_dialog_content = "... Me desculpe por sempre te arrastar para as coisas...",
  ui_story_5087_50871101_39_dialog_content = "De maneira nenhuma. Cheguei a essa decisão após muita deliberação.",
  ui_story_5087_50871101_40_dialog_content = "Eu pensei muito no nosso caminho para o Palácio Invernal. Eu pensei sobre o passado e eventos recentes...",
  ui_story_5087_50871101_41_dialog_content = "Percebi que talvez nunca fomos tão semelhantes para começar.",
  ui_story_5087_50871101_42_dialog_content = "!",
  ui_story_5087_50871101_43_dialog_content = "Prefiro um ambiente animado, mas você gosta de paz e sossego. Eu gosto de animais pequenos, mas você prefere ler...",
  ui_story_5087_50871101_44_dialog_content = "Eu posso fazer os guardas reais se afastarem para nós, mas você não pode fazer o mesmo.",
  ui_story_5087_50871101_45_dialog_content = "Huh? E-Eu vou pegar tudo o que você me mostrar...",
  ui_story_5087_50871101_46_dialog_content = "Hehe... Tudo bem. É bastante agradável saber que existem coisas que só eu posso realizar.",
  ui_story_5087_50871101_47_dialog_content = "Tenho certeza de que teremos mais discussões no futuro, porque afinal de contas, não somos iguais. É impossível para nós estarmos sempre na mesma página.",
  ui_story_5087_50871101_48_dialog_content = "Mas não é grande coisa, mesmo que a conexão que compartilhamos desapareça um dia.",
  ui_story_5087_50871101_49_dialog_content = "Enquanto eu tiver minha boca para buscar seus pensamentos e um par de pernas para me aproximar de você...",
  ui_story_5087_50871101_50_dialog_content = "Nossos corações nunca se separarão.",
  ui_story_5087_50871101_51_dialog_content = "Nepolis! Ah... Estou tão feliz em saber que você se sente assim...",
  ui_story_5087_50871101_52_dialog_content = "Você é o melhor! Nunca vou sair do seu lado! Boo-hoo...",
  ui_story_5087_50871101_53_dialog_content = "Ei! Comporte-se de acordo com sua idade! Estamos no Palácio Invernal...",
  ui_story_5087_50871101_54_dialog_content = "N-Na verdade, acabei de ter uma conversa semelhante com Shaya... Espere um minuto! Você ouviu a nossa conversa?",
  ui_story_5087_50871101_55_dialog_content = "Que conversa?",
  ui_story_5087_50871101_56_dialog_content = "Desculpe interromper, mas sinto algo poderoso me pressionando... O Espelho de Northland está por perto.",
  ui_story_5087_50871101_57_dialog_content = "O perigo pode estar à espreita à frente, e eu posso ser incapaz de lhe dar mais orientações a qualquer momento—",
  ui_story_5087_50871101_58_dialog_content = "... Está tudo bem.",
  ui_story_5087_50871101_59_dialog_content = "Então, este é o cofre do tesouro do Palácio de Inverno - o Quarto das Relíquias.",
  ui_story_5087_50871101_60_dialog_content = "Quê? Você já esteve aqui antes?",
  ui_story_5087_50871101_61_dialog_content = "Minha irmã e eu costumávamos brincar de esconde-esconde aqui quando éramos pequenas. Você ainda se lembra do tempo em que estávamos recebendo tratamento no Palácio de Inverno, Nepolis?",
  ui_story_5087_50871101_62_dialog_content = "...",
  ui_story_5087_50871101_63_dialog_content = "Népolis?",
  ui_story_5087_50871101_64_dialog_content = "Estão... vindo.",
  ui_story_5087_50871101_65_dialog_content = "Graah!",
  ui_story_5087_50871102_1_dialog_content = "Huff... Huff... Esses são alguns monstros fortes. O que eles estão fazendo no Palácio Invernal?",
  ui_story_5087_50871102_2_dialog_content = "Vamos descobrir mais tarde. Entre na Sala dos Relíquias! Rápido!",
  ui_story_5087_50871102_3_dialog_content = "O Espelho Northland! Eu sabia que te encontraria aqui...",
  ui_story_5087_50871102_4_dialog_content = "<color=#e8d9bb>O Espelho de Northland está visivelmente danificado, com rachaduras e lacunas por toda parte.</color>",
  ui_story_5087_50871102_5_dialog_content = "<color=#e8d9bb>Ainda assim, irradia um brilho suave e gentil enquanto inúmeras sombras cintilam na superfície rachada do espelho.</color>",
  ui_story_5087_50871102_6_dialog_content = "(Essas figuras me dão uma sensação tão familiar...)",
  ui_story_5087_50871102_7_dialog_content = "Es-Esse espelho! Você é a Senhora Nikinis?",
  ui_story_5087_50871102_8_dialog_content = "Acalme-se. Eu sou Nikinis, e estou aqui a mando de Queen Bethlehem.",
  ui_story_5087_50871102_9_dialog_content = "Suspeito que as relíquias antigas sejam a fonte da série de eventos estranhos que você encontrou recentemente.",
  ui_story_5087_50871102_10_dialog_content = "Como é uma questão de extrema importância, peço que me conte todos os detalhes.",
  ui_story_5087_50871102_11_dialog_content = "Muitíssimo!",
  ui_story_5087_50871102_12_dialog_content = "Graaah!",
  ui_story_5087_50871102_13_dialog_content = "Monstro vil... E-eu vou te derrubar!",
  ui_story_5087_50871102_14_dialog_content = "Monstro, saia.",
  ui_story_5087_50871102_15_dialog_content = "Graaah...",
  ui_story_5087_50871102_16_dialog_content = "Senhora Nikinis! M-Muito obrigado por me salvar!",
  ui_story_5087_50871102_17_dialog_content = "Sua vida é uma coisa pura e preciosa. Da próxima vez, chame meu nome antes de arriscar sua vida na batalha.",
  ui_story_5087_50871102_18_dialog_content = "Eu fugi da festa de comemoração novamente... Todos devem pensar que sou arrogante e irritante.",
  ui_story_5087_50871102_19_dialog_content = "Mas eu realmente não tenho ideia de como agir lá. Todos eles parecem tão felizes, e só eu...",
  ui_story_5087_50871102_20_dialog_content = "Senhora Nikinis!",
  ui_story_5087_50871102_21_dialog_content = "Você é de lá atrás—",
  ui_story_5087_50871102_22_dialog_content = "Eu vi você se esgueirar, m-mas ainda não tive a chance de te dar isso!",
  ui_story_5087_50871102_23_dialog_content = "Um buquê de narcisos e lírios...",
  ui_story_5087_50871102_24_dialog_content = "Ouvi dizer que são as suas flores favoritas.",
  ui_story_5087_50871102_25_dialog_content = "Senhora Nikinis, não posso agradecer o suficiente por sempre lutar ao nosso lado e nos proteger!",
  ui_story_5087_50871102_26_dialog_content = "(Isso foi... minha memória agora mesmo?)",
  ui_story_5087_50871102_27_dialog_content = "(Eu já fui tão inspirador e calmo? Participei de tantos eventos importantes?)",
  ui_story_5087_50871102_28_dialog_content = "<color=#e8d9bb>Como se atraída por suas memórias recuperadas, Nikinis avança em direção ao Espelho de Northland e coloca sua palma sobre ele—</color>",
  ui_story_5087_50871102_29_dialog_content = "Está inteiro novamente! ... Você realmente tem uma conexão especial com isso, Nikinis.",
  ui_story_5087_50871102_30_dialog_content = "Hum...",
  ui_story_5087_50871102_31_dialog_content = "Isso é ótimo. Agora, apenas o passo final resta!",
  ui_story_5087_50871102_32_dialog_content = "O passo final? Você não disse que tudo será revelado assim que o espelho for consertado?",
  ui_story_5087_50871102_33_dialog_content = "Nikinis, você deveria ter conseguido recuperar uma parte de suas memórias enquanto consertava o espelho.",
  ui_story_5087_50871102_34_dialog_content = "Agora... Tudo o que resta é <color=#FFB400>passar pelo espelho</color>!",
  ui_story_5087_50871102_35_dialog_content = "O quê? Passar para o outro mundo?",
  ui_story_5087_50871102_36_dialog_content = "Exatamente. É onde o verdadeiro Queen Bethlehem reside. Suas memórias restantes e as respostas que você procura também estão além do espelho!",
  ui_story_5087_50871102_37_dialog_content = "Eu não sei...",
  ui_story_5087_50871102_38_dialog_content = "Faça isso, Nikinis.",
  ui_story_5087_50871102_39_dialog_content = "Huh? Você quer que eu entre no espelho?",
  ui_story_5087_50871102_40_dialog_content = "Isso mesmo. Já chegamos tão longe. Não podemos simplesmente virar e voltar para casa, certo?",
  ui_story_5087_50871102_41_dialog_content = "Você deve recuperar suas memórias, descobrir tudo e voltar para me contar cada detalhe.",
  ui_story_5087_50871102_42_dialog_content = "Se esse espelho ousar te parar, eu não descansarei até trazer você de volta, e mostraremos a ele quem é o chefe!",
  ui_story_5087_50871102_43_dialog_content = "Então, vai logo. É uma promessa.",
  ui_story_5087_50871102_44_dialog_content = "Népolis...",
  ui_story_5087_50871102_45_dialog_content = "...",
  ui_story_5087_50871102_46_dialog_content = "Anda, Nikinis.",
  ui_story_5087_50871102_47_dialog_content = "E-Eu vou então, Nepolis!",
  ui_story_5087_50871102_48_dialog_content = "Tá bem.",
  ui_story_5087_50871102_49_dialog_content = "<color=#e8d9bb>O espelho brilha mais forte como se estivesse acolhendo Nikinis, e ela finalmente dá aquele passo—</color>",
  ui_story_5087_50871102_50_dialog_content = "<color=#e8d9bb>Efervescer.</color>",
  ui_story_5087_50871102_51_dialog_content = "Uh... Urgh! Nem... pense nisso!",
  ui_story_5087_50871102_52_dialog_content = "Qual o problema, Nepolis?",
  ui_story_5087_50871102_53_dialog_content = "Estou... bem... Depressa... Urghhhh!",
  ui_story_5087_50871102_54_dialog_content = "...",
  ui_story_5087_50871102_55_dialog_content = "Nepolis! Nepolis! Você está bem?",
  ui_story_5087_50871102_56_dialog_content = "Nikinis! Fique longe da sua irmã! Eu tenho medo que ela—",
  ui_story_5087_50871102_57_dialog_content = "... Nikinis.",
  ui_story_5087_50871102_58_dialog_content = "Estou bem aqui! Como você está se sentindo? Está ferido em algum lugar?",
  ui_story_5087_50871102_59_dialog_content = "O outro lado do espelho... é extremamente perigoso.",
  ui_story_5087_50871102_60_dialog_content = "Uhh?",
  ui_story_5087_50871102_61_dialog_content = "Não posso deixar você ir para um lugar tão perigoso. Apenas fique do meu lado, ok?",
  ui_story_5087_50871102_62_dialog_content = "M-Mas... Você acabou de dizer...",
  ui_story_5087_50871102_63_dialog_content = "Tenho medo... Tenho medo de perder você... Uma vez que você passar pelo espelho, nunca mais vou te ver.",
  ui_story_5087_50871102_64_dialog_content = "Tudo que eu preciso é de você, e acho que você também sente o mesmo, certo?",
  ui_story_5087_50871102_65_dialog_content = "Você ficaria tão sozinho sem mim... Você nem seria capaz de encarar os sorrisos das pessoas em uma festa.",
  ui_story_5087_50871102_66_dialog_content = "!",
  ui_story_5087_50871102_67_dialog_content = "Quanto mais felizes os outros estão, mais doloroso se torna para você. Porque no fundo, você sabe que sua felicidade nunca voltará...",
  ui_story_5087_50871102_68_dialog_content = "Fique comigo, minha irmã... Meu Nikinis—",
  ui_story_5087_50871102_69_dialog_content = "Nikinis, não deixe que ela te engane. Aquela não é mais sua irmã!",
  ui_story_5087_50871102_70_dialog_content = "Você deve passar pelo espelho! Você está dentro do <color=#FFB400>mundo espelhado</color> criado pelo Espelho de Northland! E este lado—",
  ui_story_5087_50871102_71_dialog_content = "É aqui que a <color=#FFB400>realidade</color> realmente reside!",
  ui_story_5087_50871102_72_dialog_content = "!",
  ui_story_5087_50871102_73_dialog_content = "Você não percebeu? Nada neste mundo parece certo!",
  ui_story_5087_50871102_74_dialog_content = "Algo não está certo... Sim, eu não me lembro dos meus pais nunca terem trabalhado no Palácio Invernal...",
  ui_story_5087_50871102_75_dialog_content = "Porque foi fabricado pelo Espelho de Northland!",
  ui_story_5087_50871102_76_dialog_content = "O Palácio Invernal está muito limpo...",
  ui_story_5087_50871102_77_dialog_content = "Porque não há sombras! Tudo aqui é uma ilusão sem sombras criada pelo espelho! Até a rainha é uma ilusão!",
  ui_story_5087_50871102_78_dialog_content = "É verdade! As velas e os móveis não têm sombras, mas eu tenho! E Nepolis...",
  ui_story_5087_50871102_79_dialog_content = "... Espere! Você está errado! Nepólis tem uma sombra! Ela é real!",
  ui_story_5087_50871102_80_dialog_content = "... Shaya ainda não chegou? Ela vai explicar tudo para você! A esta altura, suponho que posso te contar a verdade. Shaya é Bete—",
  ui_story_5087_50871102_81_dialog_content = "Ela não está vindo.",
  ui_story_5087_50871102_82_dialog_content = "Você é—",
  ui_story_5087_50871102_83_dialog_content = "<color=#e8d9bb>Nikinis olha instintivamente para os pés da rainha. Não há nada lá, nem perto dos pés dos guardas reais.</color>",
  ui_story_5087_50871102_84_dialog_content = "<color=#e8d9bb>Nada! Não há nada lá! Nenhum deles tem uma sombra!</color>",
  ui_story_5087_50871102_85_dialog_content = "<color=#e8d9bb>A \"rainha\" congela o Espelho de Northland com um movimento de sua palma, e com outro movimento, o espelho voa e se estilhaça em pedaços.</color>",
  ui_story_5087_50871102_86_dialog_content = "... Então você é um falso!",
  ui_story_5087_50871102_87_dialog_content = "Eu não sou o único. Mostrem-se, todos.",
  ui_story_5087_50871102_88_dialog_content = "Graaah!",
  ui_story_5087_50871102_89_dialog_content = "Nem pense nisso! Eu não vou deixar você machucar a Nepólis—",
  ui_story_5087_50871102_90_dialog_content = "Nepolis? Heh, você verificou minha sombra, mas não está fazendo o mesmo com ela?",
  ui_story_5087_50871102_91_dialog_content = "Não... Ela é diferente...",
  ui_story_5087_50871102_92_dialog_content = "Graah! Graaah!",
  ui_story_5087_50871102_93_dialog_content = "Por que eu fabricaria a vida dos seus pais? Porque eles só vivem neste mundo!",
  ui_story_5087_50871102_94_dialog_content = "Assim como Nepólis.",
  ui_story_5087_50871102_95_dialog_content = "Não... Pare com isso!",
  ui_story_5087_50871102_96_dialog_content = "... Caramba, nos conhecemos há tanto tempo. Pensei que você fosse mais esperto do que isso.",
  ui_story_5087_50871102_97_dialog_content = "Bem, eu vou capturá-lo primeiro, então lentamente farei você encarar a realidade.",
  ui_story_5087_50871102_98_dialog_content = "Pegue ela! Não importa se você for um pouco rude!",
  ui_story_5087_50871102_99_dialog_content = "Graaah!",
  ui_story_5087_50871102_100_dialog_content = "<color=#e8d9bb>Urgh! O golpe mais pesado não acerta Nikinis.</color>",
  ui_story_5087_50871102_101_dialog_content = "N-Népolis?",
  ui_story_5087_50871102_102_dialog_content = "<color=#e8d9bb>Nikinis observa algo escuro e indistinto fluindo da ferida de Nepolis—</color>",
  ui_story_5087_50871102_103_dialog_content = "<color=#e8d9bb>E então, ela começa a derreter no local.</color>",
  ui_story_5087_50871102_104_dialog_content = "Não... Isso não é real... Nepolis... Nepolis!",
  ui_story_5087_50871102_105_dialog_content = "N-Nikinis...",
  ui_story_5087_50871102_106_dialog_content = "Nepolis... Não! Não... Por favor, não vá—",
  ui_story_5087_50871102_107_dialog_content = "C-Corre!",
  ui_story_5087_50871102_108_dialog_content = "!",
  ui_story_5087_50871102_109_dialog_content = "<color=#e8d9bb>Inúmeros monstros avançam e varrem a figura sombria de Nepolis.</color>",
  ui_story_5087_50871102_110_dialog_content = "NÃO! Pra onde você foi, Nepolis?",
  ui_story_5087_50871102_111_dialog_content = "<color=#e8d9bb>Nikinis agarra freneticamente, mas tudo o que resta é um mero sopro de névoa escura que se dissipa em seu alcance.</color>",
  ui_story_5087_50871102_112_dialog_content = "Népolis... Népolis...",
  ui_story_5087_50871102_113_dialog_content = "Graaaaaah!",
  ui_story_5087_50871102_114_dialog_content = "...",
  ui_story_5087_50871102_115_dialog_content = "É tudo culpa sua! Vocês monstros!",
  ui_story_5087_50871102_116_dialog_content = "Graah...",
  ui_story_5087_50871102_117_dialog_content = "Você recuperou uma parte do seu poder da realidade?",
  ui_story_5087_50871102_118_dialog_content = "Nepolis, onde você está? Por favor, não me assuste assim... Ah, você foi na frente para abrir um caminho para mim, certo? Nossa, você deveria ter me dito...",
  ui_story_5087_50871102_119_dialog_content = "Estou a caminho de você!",
  ui_story_5087_50871102_120_dialog_content = "Népolis—",
  ui_story_5087_50871102_121_dialog_content = "Népolis...",
  ui_story_5087_50871102_122_dialog_content = "Nepolis, onde está você? Eu estou te implorando! Por favor, volte para mim...",
  ui_story_5087_50871102_123_dialog_content = "<color=#e8d9bb>Sem perceber, Nikinis chega à cabana onde encontrou o Espelho de Northland com Nepolis.</color>",
  ui_story_5087_50871102_124_dialog_content = "Nepolis, você veio aqui para me esperar?",
  ui_story_5087_50871102_125_dialog_content = "<color=#e8d9bb>Em meio à fragrância avassaladora das flores, as flores brancas puras feitas de Luminatics permanecem em plena floração dentro da cabana.</color>",
  ui_story_5087_50871102_126_dialog_content = "<color=#e8d9bb>Mas apenas narcisos brancos permanecem. Todos eles são narcisos brancos.</color>",
  ui_story_5087_50871102_127_dialog_content = "<color=#e8d9bb>Todos os lírios se foram, como se nunca estivessem lá, para começar.</color>",
  ui_story_5087_50871102_128_dialog_content = "N-Népolis?",
  ui_story_5087_50871102_129_dialog_content = "\"Você consegue se lembrar daquelas belas flores brancas? Dois caules crescendo em harmonia à beira do lago tranquilo.\"",
  ui_story_5087_50871102_130_dialog_content = "Não, não, não...",
  ui_story_5087_50871102_131_dialog_content = "\"Sob a neve cinza que caía, o lírio imaculado logo foi enterrado.\"",
  ui_story_5087_50871102_132_dialog_content = "\"Deixado sozinho no mundo, o narciso branco chorou silenciosamente.\"",
  ui_story_5087_50871102_133_dialog_content = "... Aaaaaaaaaaaaaaaaaaaaah!",
  ui_story_5087_50871200_1_dialog_content = "Que estranho.",
  ui_story_5087_50871200_2_dialog_content = "Mamãe e papai disseram que ela se foi, mas Nepolis sempre esteve ao meu lado.",
  ui_story_5087_50871200_3_dialog_content = "<color=#e8d9bb>Zumbido... Moscas pousam em alguma carne vermelha que está gradualmente perdendo sua forma.</color>",
  ui_story_5087_50871200_4_dialog_content = "Esse cheiro... Ah! É o ensopado de maçã da semana passada? O que está fazendo ali, Nikinis?",
  ui_story_5087_50871200_5_dialog_content = "Mesmo que você não queira comê-lo, pelo menos jogue as sobras fora! Apenas olhe para isso...",
  ui_story_5087_50871200_6_dialog_content = "Mas... Essa é a parte de Nepolis.",
  ui_story_5087_50871200_7_dialog_content = "!",
  ui_story_5087_50871200_8_dialog_content = "Que estranho. Por que a Nepolis não vai comer? Sopa de maçã é a favorita dela.",
  ui_story_5087_50871200_9_dialog_content = "Eu sei! Ela deve estar com pouco apetite ultimamente! Ela até fala menos agora... Será um efeito colateral de sua doença?",
  ui_story_5087_50871200_10_dialog_content = "Encontrei você! Agora, quem é o próximo?",
  ui_story_5087_50871200_11_dialog_content = "Ei! Deixe-nos juntar a vocês!",
  ui_story_5087_50871200_12_dialog_content = "Huh? Mas você está sozinho.",
  ui_story_5087_50871200_13_dialog_content = "O que você quer dizer? Minha irmã está bem ao meu lado! Ela tem falado menos ultimamente, mas eu sei que ela quer brincar com todos!",
  ui_story_5087_50871200_14_dialog_content = "Nossa Luminática está conectada, então eu sei tudo o que ela está pensando.",
  ui_story_5087_50871200_15_dialog_content = "... Ela é louca.",
  ui_story_5087_50871200_16_dialog_content = "Nikinis é louca! Ela ficou doida!",
  ui_story_5087_50871200_17_dialog_content = "Você é louco! Você está furioso! Minha irmã está apenas doente, e isso enfraqueceu seus Luminatics! Ela está sempre lá! Eu posso vê-la!",
  ui_story_5087_50871200_18_dialog_content = "Sua Majestade, estou implorando. Por favor, ajude Nikinis! Desde Nepolis... você sabe, ela tem estado assim desde então...",
  ui_story_5087_50871200_19_dialog_content = "Os médicos estão perplexos! Você é nossa última esperança! Estou implorando, Vossa Majestade!",
  ui_story_5087_50871200_20_dialog_content = "... A situação de suas filhas gêmeas é um caso extremamente raro.",
  ui_story_5087_50871200_21_dialog_content = "Eu tenho uma ideia, mas é muito perigoso. Deixe-me pensar um pouco mais.",
  ui_story_5087_50871200_22_dialog_content = "Seu nome é Nikinis? É um nome bonito. Como sua irmã, Nepolis, não gosta de falar, você poderia apresentá-la para mim?",
  ui_story_5087_50871200_23_dialog_content = "Você acabou de... perguntar sobre minha irmã? Graças a Deus! Alguém finalmente acredita em mim!",
  ui_story_5087_50871200_24_dialog_content = "Mas você poderia tratá-la primeiro? Ela está doente e ainda não se recuperou totalmente até agora...",
  ui_story_5087_50871200_25_dialog_content = "Nossas almas são uma só, então tratar apenas de mim não vai funcionar... Eu vou ficar bem quando ela estiver bem!",
  ui_story_5087_50871200_26_dialog_content = "...",
  ui_story_5087_50871200_27_dialog_content = "Nepolis, Nepolis! Sua Majestade definitivamente será capaz de curar você! Essa é uma ótima notícia!",
  ui_story_5087_50871200_28_dialog_content = "Sim... Eu também estou muito feliz...",
  ui_story_5087_50871200_29_dialog_content = "Então, que tal um jogo de esconde-esconde? Não é todo dia que passamos a noite no Palácio de Inverno. Vamos nos divertir!",
  ui_story_5087_50871200_30_dialog_content = "Este lugar parece realmente misterioso... Nepolis, você também sente isso?",
  ui_story_5087_50871200_31_dialog_content = "...",
  ui_story_5087_50871200_32_dialog_content = "Pequeno Aurorian... Pequeno Aurorian ali...",
  ui_story_5087_50871200_33_dialog_content = "Huh? Quem está aí? Com quem você está falando? Sou eu? Ou minha irmã?",
  ui_story_5087_50871200_34_dialog_content = "Só você pode ver sua irmã e sentir a alma dela. É solitário, não é, pequeno Aurorian...",
  ui_story_5087_50871200_35_dialog_content = "!",
  ui_story_5087_50871200_36_dialog_content = "Eu... posso te ajudar. Aproxima-te...",
  ui_story_5087_50871200_37_dialog_content = "... Um espelho? Como um espelho supostamente vai me ajudar?",
  ui_story_5087_50871200_38_dialog_content = "Pequeno Auroriano, você não sabe nada sobre o poder do espelho.",
  ui_story_5087_50871200_39_dialog_content = "Posso restaurar sua irmã à sua antiga glória. Todos poderão vê-la e senti-la—",
  ui_story_5087_50871200_40_dialog_content = "Mas você deve fazer um pacto comigo.",
  ui_story_5087_50871200_41_dialog_content = "É-É verdade? Ela vai brincar comigo, brincar comigo e lutar comigo, assim como costumava fazer?",
  ui_story_5087_50871200_42_dialog_content = "O que eu devo fazer?",
  ui_story_5087_50871200_43_dialog_content = "Dê-me sua... Lúmina.",
  ui_story_5087_50871200_44_dialog_content = "Minha Lúmina? Assim?",
  ui_story_5087_50871200_45_dialog_content = "<color=#e8d9bb>Sua jovem palma cobre o espelho—</color>",
  ui_story_5087_50871200_46_dialog_content = "A relíquia foi despertada! Está absorvendo Lumina... Notifique Sua Majestade imediatamente!",
  ui_story_5087_50871200_47_dialog_content = "Aquela criança, Nikinis... Ela ainda está inconsciente. O Espelho de Northland tirou muito Lúmina dela.",
  ui_story_5087_50871200_48_dialog_content = "Ela vai acordar novamente?",
  ui_story_5087_50871200_49_dialog_content = "O Espelho Northland escolheu-a como sua hospedeira. As chances dela de sobrevivência são escassas.",
  ui_story_5087_50871200_50_dialog_content = "... A menos que eu sele o corpo dela com o Espelho de Northland.",
  ui_story_5087_50871200_51_dialog_content = "Se ela conseguir se adaptar ao relicário e recuperar a consciência por conta própria, ela sobreviverá. Caso contrário...",
  ui_story_5087_50871200_52_dialog_content = "Acho que essa é a única solução...",
  ui_story_5087_50871200_53_dialog_content = "*suspiros* Esta é a situação exata que você estava tentando evitar ao não tratá-la com o Espelho Northland.",
  ui_story_5087_50871200_54_dialog_content = "Nunca poderíamos ter sabido que o Espelho de Northland a atrairia... Ela é tão compatível com ele?",
  ui_story_5087_50871200_55_dialog_content = "Você não pode chamar isso de \"tratamento\". É apenas utilizar o poder do Espelho de Northland no reino mental para—",
  ui_story_5087_50871200_56_dialog_content = "Remova à força os remanescentes de Luminatics deixados por sua falecida irmã.",
  ui_story_5087_50871200_57_dialog_content = "A Luminática de uma irmã permanecendo dentro da outra irmã é realmente maravilhosa.",
  ui_story_5087_50871200_58_dialog_content = "Nikinis e Nepolis são especiais. Sua conexão é tão próxima que é quase como uma única alma dividida em dois corpos.",
  ui_story_5087_50871200_59_dialog_content = "É por isso que o tratamento de Nikinis deve ser realizado com extrema cautela. Se os resquícios de sua irmã forem removidos à força—",
  ui_story_5087_50871200_60_dialog_content = "Embora ela certamente não vá \"ver\" sua irmã novamente, o tempo que passaram juntas, as memórias que compartilharam, as percepções que formaram juntas...",
  ui_story_5087_50871200_61_dialog_content = "Tudo será jogado no caos ou até mesmo desaparecerá.",
  ui_story_5087_50871200_62_dialog_content = "Não será diferente de tirar metade dela.",
  ui_story_5087_50871200_63_dialog_content = "De fato. Esse risco é impossível de eliminar, nem mesmo com a ajuda do Espelho Northland.",
  ui_story_5087_50871200_64_dialog_content = "Irmãs gêmeas conectadas tanto em mente quanto em alma, mas a irmã mais velha adoeceu...",
  ui_story_5087_50871200_65_dialog_content = "E a morte os separou... Por que o destino sempre prega essas peças em todos nós?",
  ui_story_5087_50871200_66_dialog_content = "... Mas eles estão realmente separados?",
  ui_story_5087_50871200_67_dialog_content = "Novio, você acredita que... a alma de um Auroriano existe dentro de Luminatics?",
  ui_story_5087_50871300_1_dialog_content = "(Eu me lembro agora, de tudo.)",
  ui_story_5087_50871300_2_dialog_content = "(Nepolis faleceu há muito tempo, e Queen Bethlehem me selou na caverna congelada para salvar minha vida.)",
  ui_story_5087_50871300_3_dialog_content = "(Ambos, mãe e pai, faleceram durante este período.)",
  ui_story_5087_50871300_4_dialog_content = "(Não conseguia nem me lembrar de viver com meus pais depois de recuperar a consciência...)",
  ui_story_5087_50871300_5_dialog_content = "<color=#e8d9bb>Ao abrir os olhos na caverna congelada, a Aurorian conhecida como Nikinis não tinha mais nada.</color>",
  ui_story_5087_50871300_6_dialog_content = "<color=#e8d9bb>Sem casa, cidade natal ou memórias. Ela estava sozinha no mundo com apenas seu eu frágil e incompleto.</color>",
  ui_story_5087_50871300_7_dialog_content = "<color=#e8d9bb>Além do suave brilho do espelho mágico ao seu lado, a única outra coisa a cumprimentá-la foi—</color>",
  ui_story_5087_50871300_8_dialog_content = "<color=#e8d9bb>Uma imagem sorridente de si mesma, saindo de entre os lírios totalmente florescidos refletidos na superfície do espelho.</color>",
  ui_story_5087_50871300_9_dialog_content = "\"No que você está encarando? Não reconhece sua própria irmã?\"",
  ui_story_5087_50871300_10_dialog_content = "\"Meu Nikinis... Minha outra metade...\"",
  ui_story_5087_50871300_11_dialog_content = "(Tudo isso... Essa é a minha realidade...)",
  ui_story_5087_50871300_12_dialog_content = "(Uma realidade mais cruel e terrível do que o mundo espelhado.)",
  ui_story_5087_50871300_13_dialog_content = "Então por que você não fica no espelho?",
  ui_story_5087_50871300_14_dialog_content = "...",
  ui_story_5087_50871300_15_dialog_content = "Você de novo... Você ainda tem a coragem de falar comigo tão descaradamente...",
  ui_story_5087_50871300_16_dialog_content = "É toda sua culpa!",
  ui_story_5087_50871300_17_dialog_content = "Não seja tão crítico... Tudo o que fiz foi realizar seu desejo.",
  ui_story_5087_50871300_18_dialog_content = "Você queria aproveitar a vida com sua irmã, e eu te dei isso. Você queria lutar ao lado dela, e eu também te dei isso.",
  ui_story_5087_50871300_19_dialog_content = "Mesmo as memórias da realidade que você procurou recuperar, eu as dei a você também - mesmo que isso não me beneficiasse de forma alguma.",
  ui_story_5087_50871300_20_dialog_content = "Ah, eu gostaria que você demonstrasse alguma gratidão. Meu anfitrião e contratante...",
  ui_story_5087_50871300_21_dialog_content = "Recuperei minhas próprias memórias! Nem pense em levar crédito por isso!",
  ui_story_5087_50871300_22_dialog_content = "Como foi recuperar essas memórias? Você gostou?",
  ui_story_5087_50871300_23_dialog_content = "...",
  ui_story_5087_50871300_24_dialog_content = "Não foi divertido, foi? A escuridão e o tédio da vida real são coisas que eu, o criador de ilusões, conheço melhor do que ninguém.",
  ui_story_5087_50871300_25_dialog_content = "Então, fique dentro do espelho.",
  ui_story_5087_50871300_26_dialog_content = "Posso realizar todos os seus desejos.",
  ui_story_5087_50871300_27_dialog_content = "Qualquer coisa que possa ser refletida pelo espelho é um presente meu para você.",
  ui_story_5087_50871300_28_dialog_content = "Tudo que é preciso é um pensamento para você se tornar o governante do mundo espelhado! O mundo inteiro estará aos seus pés!",
  ui_story_5087_50871300_29_dialog_content = "Ou sua ganância não é tão grande? Talvez o que você deseja seja apenas—",
  ui_story_5087_50871300_30_dialog_content = "Nikinis, eu não quero te perder de novo...",
  ui_story_5087_50871300_31_dialog_content = "Népolis!",
  ui_story_5087_50871300_32_dialog_content = "Fique comigo. Você vai realizar esse pequeno desejo meu, não vai?",
  ui_story_5087_50871300_33_dialog_content = "(Eu...)",
  ui_story_5087_50871300_34_dialog_content = "Se você permanecer dentro do espelho, posso tomar seu lugar <color=#FFB400>na realidade</color>.",
  ui_story_5087_50871300_35_dialog_content = "Os lírios florescerão mais uma vez em Northland... e até mesmo em todas as terras de Astra.",
  ui_story_5087_50871300_36_dialog_content = "... Sério? É esse o seu desejo?",
  ui_story_5087_50871300_37_dialog_content = "De uma vez só.",
  ui_story_5087_50871300_38_dialog_content = "Bem, nesse caso...",
  ui_story_5087_50871300_39_dialog_content = "Eu vou fazer isso.",
  ui_story_5087_50871400_1_dialog_content = "Não consigo acreditar que essa floresta, planícies nevadas, geada e tudo mais fazem parte da ilusão do espelho.",
  ui_story_5087_50871400_2_dialog_content = "Não é diferente da realidade!",
  ui_story_5087_50871400_3_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50871400_4_dialog_content = "O mundo espelhado não é tão ruim, ou melhor, não há nada de ruim nele de todo.",
  ui_story_5087_50871400_5_dialog_content = "Nikinis—",
  ui_story_5087_50871400_6_dialog_content = "Nepolis e meus pais, todos estão comigo novamente...",
  ui_story_5087_50871400_7_dialog_content = "Nikinis!",
  ui_story_5087_50871400_8_dialog_content = "!",
  ui_story_5087_50871400_9_dialog_content = "<color=#e8d9bb>A nevasca pesada continuou por vários dias, e o gelo e a neve em toda a Northland tornaram-se cada vez mais cristalinos. Um cristal de gelo flutua com o vento e pousa na palma de Nikinis.</color>",
  ui_story_5087_50871400_10_dialog_content = "<color=#e8d9bb>Uma figura familiar aparece na superfície do cristal de gelo.</color>",
  ui_story_5087_50871400_11_dialog_content = "O que está no espelho!",
  ui_story_5087_50871400_12_dialog_content = "Não... Eu me lembro agora. Você é... PlayerName.",
  ui_story_5087_50871400_13_dialog_content = "Você encontrou este lugar... Você passou por todo esse trabalho apenas para me trazer de volta à realidade?",
  ui_story_5087_50871400_14_dialog_content = "Você se lembra de tudo? Que alívio! Agora escute, nós devemos—",
  ui_story_5087_50871400_15_dialog_content = "... Já chega.",
  ui_story_5087_50871400_16_dialog_content = "Uhh?",
  ui_story_5087_50871400_17_dialog_content = "Eu aprecio o que você fez. Durante meu tempo vivendo na realidade, nunca imaginei que alguém iria tão longe por mim.",
  ui_story_5087_50871400_18_dialog_content = "Mas está tudo bem agora. Descanse um pouco. Você não precisa mais perder tempo me procurando.",
  ui_story_5087_50871400_19_dialog_content = "Pretendo ficar dentro do espelho.",
  ui_story_5087_50871400_20_dialog_content = "... É por causa da sua irmã?",
  ui_story_5087_50871400_21_dialog_content = "Minha \"irmã\"... De fato.",
  ui_story_5087_50871400_22_dialog_content = "Embora ela seja apenas uma ilusão criada pelo Espelho de Northland, extraindo os remanescentes de sua Luminática de dentro de mim...",
  ui_story_5087_50871400_23_dialog_content = "Ela ainda é a mesma irmã que eu conhecia.",
  ui_story_5087_50871400_24_dialog_content = "Ela deseja viver na realidade novamente, e os lírios desejam florescer por todo Northland...",
  ui_story_5087_50871400_25_dialog_content = "Como eu poderia recusar seu único desejo?",
  ui_story_5087_50871400_26_dialog_content = "É realmente isso que Nepólis quer? É provável que o espelho mágico esteja usando a imagem dela novamente para que você fique!",
  ui_story_5087_50871400_27_dialog_content = "Assim como fez na Sala dos Relíquias! Ele quer que você fique no espelho para que possa assumir o controle total do seu corpo—",
  ui_story_5087_50871400_28_dialog_content = "Isso ainda não vai mudar minha decisão.",
  ui_story_5087_50871400_29_dialog_content = "?",
  ui_story_5087_50871400_30_dialog_content = "Se a consciência de Nepólis permanecer, e ela desejar retornar à realidade com a ajuda do espelho...",
  ui_story_5087_50871400_31_dialog_content = "Então não posso ir contra os desejos dela e extinguir sua esperança de viver.",
  ui_story_5087_50871400_32_dialog_content = "Se Nepólis foi devorada pelo espelho, e apenas uma ilusão dela permanece...",
  ui_story_5087_50871400_33_dialog_content = "Isso prova que o Espelho de Northland tomou completamente metade da minha alma.",
  ui_story_5087_50871400_34_dialog_content = "Se eu retornar à realidade nesse estado, nem eu posso prever que tipo de coisas terríveis posso ser manipulado a fazer.",
  ui_story_5087_50871400_35_dialog_content = "... É provável que eu até te machuque.",
  ui_story_5087_50871400_36_dialog_content = "Agora não é hora de se preocupar comigo!",
  ui_story_5087_50871400_37_dialog_content = "Eu não tenho o direito de ignorar seu bem-estar quando você se recusa a me abandonar!",
  ui_story_5087_50871400_38_dialog_content = "Escute-me! Eu não acho que Nepolis—",
  ui_story_5087_50871400_39_dialog_content = "PlayerName, diga a Sua Majestade para me selar novamente.",
  ui_story_5087_50871400_40_dialog_content = "É a única maneira que eu posso proteger tanto Nepolis quanto você—",
  ui_story_5087_50871400_41_dialog_content = "NÃO! Apenas me escute!",
  ui_story_5087_50871400_42_dialog_content = "O quê...",
  ui_story_5087_50871400_43_dialog_content = "Há uma terceira possibilidade!",
  ui_story_5087_50871400_44_dialog_content = "Uma terceira... possibilidade?",
  ui_story_5087_50871400_45_dialog_content = "De acordo com você, Nepólis escolheu voluntariamente o Espelho de Northland, ou o espelho a devorou há muito tempo...",
  ui_story_5087_50871400_46_dialog_content = "Mas essas não são as únicas possibilidades!",
  ui_story_5087_50871400_47_dialog_content = "E se a consciência dela permanecer, e... ela ainda estiver resistindo ao espelho?",
  ui_story_5087_50871400_48_dialog_content = "Ela havia sucumbido ao controle do espelho na Sala dos Relíquias...",
  ui_story_5087_50871400_49_dialog_content = "... Mas ela não recuperou a consciência no último momento e te salvou?",
  ui_story_5087_50871400_50_dialog_content = "!",
  ui_story_5087_50871400_51_dialog_content = "N-Nikinis...",
  ui_story_5087_50871400_52_dialog_content = "C-Corre!",
  ui_story_5087_50871400_53_dialog_content = "Ver você escapar do controle do espelho e viver uma boa vida é o que Nepólis <color=#FFB400>deseja verdadeiramente</color>!",
  ui_story_5087_50871400_54_dialog_content = "Nepólis... Seu verdadeiro desejo? Ela não quer que eu fique no espelho? Ela não quer que eu fique ao lado dela?",
  ui_story_5087_50871400_55_dialog_content = "... Claro que ela quer estar com você.",
  ui_story_5087_50871400_56_dialog_content = "Mas ela preferiria ver você abrir suas asas, voar alto e se tornar uma alma livre e independente!",
  ui_story_5087_50871400_57_dialog_content = "Eu me recuso a arrancar suas asas.",
  ui_story_5087_50871400_58_dialog_content = "Faça isso, Nikinis.",
  ui_story_5087_50871400_59_dialog_content = "Você deve recuperar suas memórias, descobrir tudo e voltar para me contar cada detalhe.",
  ui_story_5087_50871400_60_dialog_content = "Então, vai logo. É uma promessa.",
  ui_story_5087_50871400_61_dialog_content = "Por quê... Nepolis? V-Você realmente ainda está ao meu lado?",
  ui_story_5087_50871400_62_dialog_content = "Mesmo após perder sua forma física, ela ainda permanece e deseja protegê-lo.",
  ui_story_5087_50871400_63_dialog_content = "Volte, Nikinis! Apenas retorne à realidade. Você pode deixar o espelho e Nepólis para Shaya.",
  ui_story_5087_50871400_64_dialog_content = "Tenho certeza que ela vai encontrar um jeito!",
  ui_story_5087_50871400_65_dialog_content = "Shaya... Rosas amarelas e não-me-esqueças... Ah! Não me diga—",
  ui_story_5087_50871400_66_dialog_content = "Ah, e tem outra coisa que você entendeu errado.",
  ui_story_5087_50871400_67_dialog_content = "Nunca fui o único que faria tudo ao seu alcance por você.",
  ui_story_5087_50871400_68_dialog_content = "Vossa Majestade, sempre quis apresentar estas flores a você, pois elas simbolizam—",
  ui_story_5087_50871400_69_dialog_content = "Uma amizade valorizada, certo?",
  ui_story_5087_50871400_70_dialog_content = "Você tem vagado pelos jardins por tantos dias que comecei a me perguntar quando finalmente estaria disposto a me dar essas flores.",
  ui_story_5087_50871400_71_dialog_content = "Shaya é a verdadeira Queen Bethlehem.",
  ui_story_5087_50871400_72_dialog_content = "Ela entrou no mundo espelhado para te trazer de volta!",
  ui_story_5087_50871501_1_dialog_content = "Sua Majestade declarou Nikinis cúmplice do roubo no Palácio de Inverno! Ela está atualmente em fuga! Esconder ou ajudá-la é um crime!",
  ui_story_5087_50871501_2_dialog_content = "Os ladrões usarão espelhos para causar estragos. Pessoas de Northland!",
  ui_story_5087_50871501_3_dialog_content = "Destrua todos os espelhos imediatamente! Qualquer coisa que possa refletir a imagem de uma pessoa deve ser destruída!",
  ui_story_5087_50871501_4_dialog_content = "Graah!",
  ui_story_5087_50871501_5_dialog_content = "Graah...",
  ui_story_5087_50871501_6_dialog_content = "Como está a situação, Nikinis? Urgh, esses monstros simplesmente não desistem...",
  ui_story_5087_50871501_7_dialog_content = "Não é tão ruim. Qual é o meu próximo passo?",
  ui_story_5087_50871501_8_dialog_content = "... Dê-me um momento para pensar. O Espelho Northland percebeu minhas intenções e está tentando destruir todas as saídas...",
  ui_story_5087_50871501_9_dialog_content = "A ordem para destruir todos os espelhos?",
  ui_story_5087_50871501_10_dialog_content = "Isso mesmo. Os espelhos são passagens para a realidade. A estabilidade e a conectividade de uma passagem são proporcionais à área de superfície e à refletância do espelho.",
  ui_story_5087_50871501_11_dialog_content = "Este pequeno cristal de gelo é capaz de facilitar a comunicação entre nós, no máximo. Não é suficiente para trazê-lo de volta à realidade.",
  ui_story_5087_50871501_12_dialog_content = "Então eu preciso de um espelho grande e suave?",
  ui_story_5087_50871501_13_dialog_content = "Exatamente. O próprio Espelho de Northland é a melhor passagem. Shaya entrou neste mundo através dele e o roubou...",
  ui_story_5087_50871501_14_dialog_content = "O plano era garantir nosso passagem antes de convencê-lo a retornar à realidade.",
  ui_story_5087_50871501_15_dialog_content = "Infelizmente, a falsa rainha estava um passo à nossa frente e ordenou que os monstros que habitam no Espelho de Northland o destruíssem...",
  ui_story_5087_50871501_16_dialog_content = "... Ela destruiu o espelho? E ela até encenou para fazer minha irmã e eu procurarmos por ele!",
  ui_story_5087_50871501_17_dialog_content = "PlayerName, você conhece o Palácio Invernal como a palma da sua mão—",
  ui_story_5087_50871501_18_dialog_content = "Existe uma maneira de entrar sorrateiramente na Sala de Relíquias novamente e chegar ao Espelho de Northland?",
  ui_story_5087_50871501_19_dialog_content = "Temo que a Sala de Relíquias seja provavelmente o local mais fortemente guardado em Northland...",
  ui_story_5087_50871501_20_dialog_content = "Então, devemos esquecer o Espelho Northland e focar em encontrar outro caminho.",
  ui_story_5087_50871501_21_dialog_content = "Agora que a falsa rainha ordenou a destruição de todos os espelhos, garantir outra passagem não será nada fácil... Mas você está certo! Não há outra maneira!",
  ui_story_5087_50871501_22_dialog_content = "Você está inesperadamente calmo, Nikinis. Parece que estou olhando para sua figura impressionante e indomável no campo de batalha novamente.",
  ui_story_5087_50871501_23_dialog_content = "... Porque Nepolis se foi.",
  ui_story_5087_50871501_24_dialog_content = "Eu não tinha ninguém para contar ou me mimar naquela época.",
  ui_story_5087_50871501_25_dialog_content = "Nikinis...",
  ui_story_5087_50871501_26_dialog_content = "Você escolheu seguir o caminho sem sua irmã.",
  ui_story_5087_50871501_27_dialog_content = "!",
  ui_story_5087_50871501_28_dialog_content = "<color=#e8d9bb>A neve deriva com o vento, como soldados ameaçadores assobiando ao vento enquanto respondem ao chamado dos tambores de batalha—</color>",
  ui_story_5087_50871501_29_dialog_content = "<color=#e8d9bb>Acompanhando a figura que se aproxima a pé e se curvando diante de seu olhar gélido.</color>",
  ui_story_5087_50871501_30_dialog_content = "É a \"rainha\"! Entre todas as reflexões do Espelho de Northland...",
  ui_story_5087_50871501_31_dialog_content = "... Ela é a mais forte.",
  ui_story_5087_50871501_32_dialog_content = "Já que você está ciente disso, apenas se renda, Nikinis.",
  ui_story_5087_50871501_33_dialog_content = "Uma vida tranquila e aconchegante com seus pais e irmã. Basta dizer a palavra e será sua.",
  ui_story_5087_50871501_34_dialog_content = "... Mas eu devo me deitar na neve escura e esquecer minhas asas.",
  ui_story_5087_50871501_35_dialog_content = "Você realmente quer essas asas parcialmente destruídas?",
  ui_story_5087_50871501_36_dialog_content = "Eles só trarão dor para você. Cada batida infrutífera dessas asas é um lembrete—",
  ui_story_5087_50871501_37_dialog_content = "Isso me lembra que Nepolis já esteve aqui.",
  ui_story_5087_50871501_38_dialog_content = "!",
  ui_story_5087_50871501_39_dialog_content = "Isso me lembra da alegria e liberdade que compartilhamos enquanto voávamos juntos.",
  ui_story_5087_50871501_40_dialog_content = "Nepolis ficaria desapontada se eu abandonasse essas memórias.",
  ui_story_5087_50871501_41_dialog_content = "Eu nunca vou decepcionar minha irmã.",
  ui_story_5087_50871501_42_dialog_content = "... Se essa é a sua decisão—",
  ui_story_5087_50871501_43_dialog_content = "Nikinis! Cuidado!",
  ui_story_5087_50871501_44_dialog_content = "Ugh!",
  ui_story_5087_50871501_45_dialog_content = "<color=#e8d9bb>A neve varre uma sombra que parece quase congelar o mundo ao seu redor.</color>",
  ui_story_5087_50871501_46_dialog_content = "<color=#e8d9bb>A força da \"rainha\" está muito além da maioria dos Aurorianos.</color>",
  ui_story_5087_50871501_47_dialog_content = "<color=#e8d9bb>Nikinis dá tudo de si, mas mal consegue se defender e o pequeno cristal de gelo em sua mão.</color>",
  ui_story_5087_50871501_48_dialog_content = "Esse cristal de gelo frágil é o seu último espelho? Que pena.",
  ui_story_5087_50871501_49_dialog_content = "Cada floco de neve em Northland... é um súdito meu!",
  ui_story_5087_50871501_50_dialog_content = "... Eu não vou... deixar você... pegar meu espelho! Aaaah!",
  ui_story_5087_50871501_51_dialog_content = "Espelho... Espere um minuto! Ainda temos mais um espelho! Como eu pude esquecer?",
  ui_story_5087_50871501_52_dialog_content = "Bem, não é tão tarde.",
  ui_story_5087_50871501_53_dialog_content = "!",
  ui_story_5087_50871501_54_dialog_content = "Shaya? Não, você é...",
  ui_story_5087_50871501_55_dialog_content = "Ambos fizeram bem, PlayerName e Nikinis.",
  ui_story_5087_50871501_56_dialog_content = "E você... Acredito que um acerto de contas está em ordem.",
  ui_story_5087_50871501_57_dialog_content = "...",
  ui_story_5087_50871501_58_dialog_content = "Dance para mim! Neve de Northland!",
  ui_story_5087_50871502_1_dialog_content = "<color=#e8d9bb>A neve prateada dispara pelo ar majestosamente e impede que a neve escura e furiosa se aproxime.</color>",
  ui_story_5087_50871502_2_dialog_content = "Saia do meu caminho.",
  ui_story_5087_50871502_3_dialog_content = "Pare de tentar ser o herói quando você é apenas um cão vadio que tem que se esgueirar para o Palácio de Inverno!",
  ui_story_5087_50871502_4_dialog_content = "Você não é a rainha aqui!",
  ui_story_5087_50871502_5_dialog_content = "... Você não sabe nada sobre governar.",
  ui_story_5087_50871502_6_dialog_content = "A neve de Northland não precisa de um soberano. Nem os nortistas que coexistem com a neve requerem grilhões desnecessários.",
  ui_story_5087_50871502_7_dialog_content = "O único motivo da existência do soberano é herdar o poder de proteger Northland.",
  ui_story_5087_50871502_8_dialog_content = "Eu posso ser a rainha, mas antes de tudo sou uma guerreira de Northland—",
  ui_story_5087_50871502_9_dialog_content = "Você acha que vou deixar você encostar nas minhas amigos? Por que você não tenta passar pela minha nevasca primeiro?",
  ui_story_5087_50871502_10_dialog_content = "(Sua Majestade...)",
  ui_story_5087_50871502_11_dialog_content = "Que ridículo!",
  ui_story_5087_50871502_12_dialog_content = "Ninguém é páreo para mim no mundo do espelho!",
  ui_story_5087_50871502_13_dialog_content = "Vossa Majestade, deixe-me ajudá-lo! Urgh! Oh não—",
  ui_story_5087_50871502_14_dialog_content = "<color=#e8d9bb>Vendavais prateados e neve escura se chocam como behemoths que poderiam virar o mundo de cabeça para baixo.</color>",
  ui_story_5087_50871502_15_dialog_content = "<color=#e8d9bb>Em um momento de descuido, o pequeno cristal de gelo escapa do aperto de Nikinis e é levado pela tempestade.</color>",
  ui_story_5087_50871502_16_dialog_content = "PlayerName!",
  ui_story_5087_50871502_17_dialog_content = "Não se preocupe comigo! Corra para o <color=#FFB400>Lago Espelho</color>!",
  ui_story_5087_50871502_18_dialog_content = "Lago Espelho... Esse é o seu lar! E é o seu... último passadiço...",
  ui_story_5087_50871502_19_dialog_content = "É o maior, mais brilhante e estável espelho de Northland - além de ser o mais familiar para você!",
  ui_story_5087_50871502_20_dialog_content = "<color=#e8d9bb>O cristal de gelo é engolido pela tempestade, e a voz do Celestita não é mais ouvida.</color>",
  ui_story_5087_50871502_21_dialog_content = "<color=#e8d9bb>Apenas o assobio dos vendavais nevados permanece ao redor de Nikinis.</color>",
  ui_story_5087_50871502_22_dialog_content = "<color=#e8d9bb>Aqueles que fariam tudo ao seu alcance por ela ainda estão lutando por ela neste exato momento, e essa é a prova.</color>",
  ui_story_5087_50871502_23_dialog_content = "Obrigado, Shaya... Queen Bethlehem...",
  ui_story_5087_50871502_24_dialog_content = "Eu não vou deixar você para baixo!",
  ui_story_5087_50871601_1_dialog_content = "<color=#e8d9bb>O mundo pode mudar, e tempestades podem se enfurecer, mas o Lago Espelho permanece inalterado.</color>",
  ui_story_5087_50871601_2_dialog_content = "<color=#e8d9bb>Descansa lá tranquilamente entre as montanhas, claro como um espelho, e sempre o mesmo.</color>",
  ui_story_5087_50871601_3_dialog_content = "<color=#e8d9bb>Concede uma brisa refrescante, ar pacífico e suave fragrância floral à figura elegante de Nikinis.</color>",
  ui_story_5087_50871601_4_dialog_content = "<color=#e8d9bb>O aroma suave, porém rico, de flores brancas puras.</color>",
  ui_story_5087_50871601_5_dialog_content = "(O campo de flores junto ao Lago Espelho... Apenas alguns dias atrás, eu estava apreciando a vista aqui com Nepolis...)",
  ui_story_5087_50871601_6_dialog_content = "<color=#e8d9bb>Nikinis acaricia gentilmente as flores brancas. Narcisos e lírios crescem em harmonia à beira do lago tranquilo.</color>",
  ui_story_5087_50871601_7_dialog_content = "<color=#e8d9bb>Uma cena pitoresca que nunca deixa de fazer seu coração palpitar. Ela nunca para de tentar descobrir o significado disso.</color>",
  ui_story_5087_50871601_8_dialog_content = "Vamos tentar mais uma vez, PlayerName. Eu preferiria não ser condenado a uma vida à deriva, arrogante, chata e sem memórias...",
  ui_story_5087_50871601_9_dialog_content = "E nem mesmo sabendo o motivo da minha infelicidade.",
  ui_story_5087_50871601_10_dialog_content = "Estou começando a lembrar das coisas... Por favor, me ajude novamente com suas habilidades psíquicas!",
  ui_story_5087_50871601_11_dialog_content = "Tudo bem... Mas não se esforce demais. Vamos parar se você sentir algum desconforto, ok?",
  ui_story_5087_50871601_12_dialog_content = "\"Você consegue se lembrar...\"",
  ui_story_5087_50871601_13_dialog_content = "!",
  ui_story_5087_50871601_14_dialog_content = "<color=#e8d9bb>Um fogo alegre queima na lareira, sua luz quente cria sombras dançantes dentro da pequena cabana.</color>",
  ui_story_5087_50871601_15_dialog_content = "<color=#e8d9bb>No brilho do fogo, quatro figuras podem ser vistas: um marido e esposa, bem como suas filhas gêmeas que parecem imagens espelhadas uma da outra.</color>",
  ui_story_5087_50871601_16_dialog_content = "\"Você consegue se lembrar daquelas belas flores brancas? Um par crescendo em harmonia à beira do lago tranquilo.\"",
  ui_story_5087_50871601_17_dialog_content = "...",
  ui_story_5087_50871601_18_dialog_content = "\"PlayerName, eu me lembro agora.\"",
  ui_story_5087_50871601_19_dialog_content = "\"É apenas uma breve memória de nossos pais contando uma história para nós.\"",
  ui_story_5087_50871601_20_dialog_content = "\"Mas tenho certeza de que essa memória está escondendo a verdade por trás das minhas memórias perdidas...\"",
  ui_story_5087_50871601_21_dialog_content = "\"Por que não me lembro de viver com meus pais?\"",
  ui_story_5087_50871601_22_dialog_content = "\"Por que Nepólis está confinada a viver dentro do espelho?\"",
  ui_story_5087_50871601_23_dialog_content = "\"Por que eu estou sempre infeliz como se houvesse um abismo sem fundo no meu coração?\"",
  ui_story_5087_50871601_24_dialog_content = "\"As respostas que procuro estão definitivamente escondidas dentro do espelho mágico que nunca saiu do meu lado...\"",
  ui_story_5087_50871601_25_dialog_content = "\"Então, estou indo para o espelho. Nepólis está lá, e finalmente vou para o lado dela.\"",
  ui_story_5087_50871601_26_dialog_content = "\"Obrigado, PlayerName.\"",
  ui_story_5087_50871601_27_dialog_content = "É isso para a minha mensagem.",
  ui_story_5087_50871601_28_dialog_content = "<color=#e8d9bb>O espelho espera à frente com um brilho suave e gentil, assim como o dia em que Nikinis acordou na caverna congelada.</color>",
  ui_story_5087_50871601_29_dialog_content = "<color=#e8d9bb>Nikinis respira fundo e dá um passo em direção à sua imagem no espelho...</color>",
  ui_story_5087_50871601_30_dialog_content = "(É assim que entrei no mundo do espelho e acordei neste campo de flores...)",
  ui_story_5087_50871601_31_dialog_content = "(Caminhei de mãos dadas com minha irmã e me entreguei à alegria despreocupada que este lugar tinha a oferecer.)",
  ui_story_5087_50871601_32_dialog_content = "(Se eu pudesse me imergir neste sonho... Mas—)",
  ui_story_5087_50871601_33_dialog_content = "Nikinis, trouxe novos bulbos de lírio para você. Podemos plantá-los no espaço vazio ali!",
  ui_story_5087_50871601_34_dialog_content = "Uau! A beleza do campo de flores de Nikinis nunca para de crescer! Vou trazer algumas sementes na próxima vez.",
  ui_story_5087_50871601_35_dialog_content = "(O campo de flores é tão exuberante e bonito com a ajuda de inúmeros nortistas.)",
  ui_story_5087_50871601_36_dialog_content = "Nikinis, vou ajudar a arar o solo! Ho! Está realmente congelado sólido.",
  ui_story_5087_50871601_37_dialog_content = "Vou ajudar com a rega!",
  ui_story_5087_50871601_38_dialog_content = "(É a água derretida da neve de Northland que permite que os delicados narcisos brotem e floresçam.)",
  ui_story_5087_50871601_39_dialog_content = "Esse sonho... É hora de acordar.",
  ui_story_5087_50871601_40_dialog_content = "Por quê? Você esqueceu o final da história?",
  ui_story_5087_50871601_41_dialog_content = "O final...",
  ui_story_5087_50871601_42_dialog_content = "\"A partir daquele dia, uma flor de lírio brotou do narciso, e ambos viveram felizes para sempre.\"",
  ui_story_5087_50871601_43_dialog_content = "Como você pode pensar em me abandonar novamente depois de me prometer um final como aquele?",
  ui_story_5087_50871601_44_dialog_content = "Nikinis!",
  ui_story_5087_50871601_45_dialog_content = "Não, não é isso! Eu—",
  ui_story_5087_50871601_46_dialog_content = "<color=#e8d9bb>Nikinis está prestes a se defender quando fica em silêncio ao ver sua \"irmã.\"</color>",
  ui_story_5087_50871601_47_dialog_content = "Você não é minha irmã... Você é o espelho...",
  ui_story_5087_50871601_48_dialog_content = "Afinal, Nepolis perdeu para você...",
  ui_story_5087_50871601_49_dialog_content = "Perder? Ganhar? É tudo imaginação sua, Nikinis.",
  ui_story_5087_50871601_50_dialog_content = "Eu sou sua irmã, e ela sou eu. A única opção que você tem é acreditar!",
  ui_story_5087_50871601_51_dialog_content = "Caso contrário, não te deixaria sem escolha a não ser lutar comigo?",
  ui_story_5087_50871601_52_dialog_content = "Eu...",
  ui_story_5087_50871601_53_dialog_content = "Me impedindo, me esmagando, pisoteando meus desejos e destruindo minha esperança de sobreviver... Você realmente é capaz de tudo isso?",
  ui_story_5087_50871601_54_dialog_content = "Você não pode, pode? Porque você é Nikinis, o narciso que ama o lírio...",
  ui_story_5087_50871601_55_dialog_content = "Não, eu... Você não é...",
  ui_story_5087_50871601_56_dialog_content = "Agora, retorne ao meu lado. Permita-me substituí-lo e buscar a liberdade... Urgh—",
  ui_story_5087_50871601_57_dialog_content = "Urgh... Aaaaahhh!",
  ui_story_5087_50871601_58_dialog_content = "... Nikinis...",
  ui_story_5087_50871601_59_dialog_content = "Népolis?",
  ui_story_5087_50871601_60_dialog_content = "Nepolis, é você? Ainda está aqui? Você realmente está... Não é minha imaginação. Você não perdeu para isso—",
  ui_story_5087_50871601_61_dialog_content = "... O final... da história...",
  ui_story_5087_50871601_62_dialog_content = "O final? Entendi. Então você realmente deseja viver novamente, certo?",
  ui_story_5087_50871601_63_dialog_content = "Claro, é apenas justo que você viva e tome meu lugar na realidade—",
  ui_story_5087_50871601_64_dialog_content = "Não...",
  ui_story_5087_50871601_65_dialog_content = "?",
  ui_story_5087_50871601_66_dialog_content = "\"Embora o lírio tenha retornado, sua pureza foi perdida. Ela se tornou uma flor negra manchada de preto pela neve contaminada.\"",
  ui_story_5087_50871601_67_dialog_content = "Isso é... o verdadeiro final...",
  ui_story_5087_50871601_68_dialog_content = "Nepolis, o que você está dizendo...",
  ui_story_5087_50871601_69_dialog_content = "O espelho mágico e eu agora somos inseparáveis, e eu não sou mais quem eu era. É hora... de eu ir.",
  ui_story_5087_50871601_70_dialog_content = "Mas é diferente para você.",
  ui_story_5087_50871601_71_dialog_content = "Eu não quero ouvir mais nenhuma palavra! Nepolis... Tudo vai ficar bem...",
  ui_story_5087_50871601_72_dialog_content = "Nikinis, minha amada irmã, não se deitará na neve escura.",
  ui_story_5087_50871601_73_dialog_content = "Ela atravessará a neve e superará o sofrimento trazido pelo destino...",
  ui_story_5087_50871601_74_dialog_content = "Ela irá além da proteção de sua irmã para ver o mundo e amar mais pessoas...",
  ui_story_5087_50871601_75_dialog_content = "Ela crescerá digna e forte para proteger o legado, as fábulas e os poemas de Northland, e espalhará a bênção das flores para terras distantes...",
  ui_story_5087_50871601_76_dialog_content = "Ela vai pegar o que foi esquecido, retomar o que foi perdido, e escrever um fim para o nosso poema para que uma nova ode possa nascer!",
  ui_story_5087_50871601_77_dialog_content = "Então, lute.",
  ui_story_5087_50871601_78_dialog_content = "!",
  ui_story_5087_50871601_79_dialog_content = "Esmague-me, destrua-me e acabe comigo, para que o espelho mágico não tenha mais nada em que se apoiar!",
  ui_story_5087_50871601_80_dialog_content = "Deixe-me devolver o futuro que você merece, para que você possa voar alto com suas asas—",
  ui_story_5087_50871601_81_dialog_content = "Eu acredito em você.",
  ui_story_5087_50871601_82_dialog_content = "Népolis...",
  ui_story_5087_50871601_83_dialog_content = "Urgh... Urgh... Aaaah!",
  ui_story_5087_50871601_84_dialog_content = "Hehe... No final, você ainda se recusa teimosamente a abraçar o único caminho para a felicidade, não é? Minha irmã...",
  ui_story_5087_50871601_85_dialog_content = "NEPÓLIS! Aahhhh!",
  ui_story_5087_50871602_1_dialog_content = "<color=#e8d9bb>O reflexo verde escuro da Aurora serpenteia pelas águas do Lago Espelho como uma cobra deslizando sob sua superfície.</color>",
  ui_story_5087_50871602_2_dialog_content = "<color=#e8d9bb>Os gritos e estrondos da batalha se dissiparam. Claro como um espelho, e o mesmo de sempre, eternamente Lago Espelho.</color>",
  ui_story_5087_50871602_3_dialog_content = "...",
  ui_story_5087_50871602_4_dialog_content = "<color=#e8d9bb>\"Eu estarei lá quando você precisar de mim...\"</color>",
  ui_story_5087_50871602_5_dialog_content = "<color=#e8d9bb>As últimas palavras de Nepolis permanecem ecoando nos ouvidos de Nikinis.</color>",
  ui_story_5087_50871602_6_dialog_content = "<color=#e8d9bb>Ela fica lá em silêncio entre as pétalas brancas puras, despedaçadas e flutuantes.</color>",
  ui_story_5087_50871602_7_dialog_content = "<color=#e8d9bb>O aroma floral inebriante preenche o ar.</color>",
  ui_story_5087_50871602_8_dialog_content = "Nikinis! Você conseguiu!",
  ui_story_5087_50871602_9_dialog_content = "Se você não tivesse parado o espelho mágico a tempo, PlayerName e eu não teríamos saído vivos! Você nos salvou!",
  ui_story_5087_50871602_10_dialog_content = "... Isso foi aterrorizante! Não acho que conseguirei suportar a visão da neve novamente...",
  ui_story_5087_50871602_11_dialog_content = "Não diga isso! Você vai se cansar de ver tanta neve em Northland.",
  ui_story_5087_50871602_12_dialog_content = "Nikinis, me desculpe por fazer você enfrentar tudo sozinho...",
  ui_story_5087_50871602_13_dialog_content = "Estou bem, Sua Majestade. E... PlayerName—",
  ui_story_5087_50871602_14_dialog_content = "Obrigado.",
  ui_story_5087_50871602_15_dialog_content = "... Você não parece que precisa de mais convencimento.",
  ui_story_5087_50871602_16_dialog_content = "Te vejo do outro lado!",
  ui_story_5087_50871602_17_dialog_content = "Ei! E-Espere um minuto! Shaya! O que você está fazendo... Ahhhhh! Nós vamos pular? Eu preciso de mais tempo para me preparar para isso—",
  ui_story_5087_50871602_18_dialog_content = "<color=#e8d9bb>Splash! Ondulações surgem pelo lago, mas logo fica tranquilo novamente.</color>",
  ui_story_5087_50871602_19_dialog_content = "<color=#e8d9bb>O aroma das flores flutua passado Nikinis. Ela é mais uma vez deixada sozinha entre as flores no campo.</color>",
  ui_story_5087_50871602_20_dialog_content = "Népolis...",
  ui_story_5087_50871602_21_dialog_content = "Hora de partir para o mundo pelo qual você lutou tanto por mim... o mundo sem você.",
  ui_story_5087_50871602_22_dialog_content = "Eu preciso viver bem mesmo que você não esteja lá... Certo?",
  ui_story_5087_50871602_23_dialog_content = "<color=#e8d9bb>Nikinis se aproxima gradualmente do Lago Espelho. Se ao menos ela pudesse ficar um pouco mais perto do lago, apenas um pouco mais.</color>",
  ui_story_5087_50871602_24_dialog_content = "<color=#e8d9bb>Infelizmente, ela só precisa dar alguns passos para chegar à borda. Nikinis olha para baixo enquanto a água do lago molha a barra de seu vestido—</color>",
  ui_story_5087_50871602_25_dialog_content = "N-Népolis?",
  ui_story_5087_50871602_26_dialog_content = "<color=#e8d9bb>As figuras de Nikinis e Nepolis são refletidas na superfície do lago.</color>",
  ui_story_5087_50871602_27_dialog_content = "<color=#e8d9bb>Os gêmeos dançam à beira do lago, acompanhados por flocos de branco puro que flutuam com o vento - uma dança de neve à deriva e pétalas caindo.</color>",
  ui_story_5087_50871602_28_dialog_content = "<color=#e8d9bb>Dança! Dança eternamente até o fim dos tempos!</color>",
  ui_story_5087_50871602_29_dialog_content = "<color=#e8d9bb>Este seria um final verdadeiramente maravilhoso para a história - um belo poema conhecido apenas pelo vento e pela neve.</color>",
  ui_story_5087_50871602_30_dialog_content = "Minha irmã... estarei lá quando você precisar de mim...",
  ui_story_5087_50871602_31_dialog_content = "<color=#e8d9bb>Splash! Ondulações surgem através do lago mais uma vez.</color>",
  ui_story_5087_50871602_32_dialog_content = "<color=#e8d9bb>Ainda assim, a bela e poética reflexão permanece.</color>",
  ui_story_5087_50871602_33_dialog_content = "<color=#e8d9bb>Permanece cercado pela neve, cintilando dentro do espelho...</color>"
}
return config
